var e=JSON.parse(`[{"id":"v_cd99ebc0","type":"vote","entryId":"3b7643da","votedBelt":"Blue","comment":"Red Wanderer - Mine was mastered I think, and pretty easy bitting. No false gates of any sort. I only rank it above something like a zarker because of the number of discs and some slight difficulty getting the tensioner in the right spot.","userId":"XoUDXU5McjTuVnPA1xfmzytcKuy2","displayName":"Red Wanderer","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.725Z","updatedAt":"2026-10-09T23:22:56.725Z"},{"id":"v_b13ce78f","type":"vote","entryId":"3b7643da","votedBelt":"Green","comment":"LockPickingFisherman\\nFeedback is very clear. Spinner profile might require some lite modification to a DD tool. Front tensioned. My lock has 8 discs but 6 of them are zeros. The two discs I had to turn feel like they have false gates. True gates have a lot of play and are obvious. Even with 5 or six non-zeros, I can't see this being harder than green. I really want to vote orange but with so many zeros, I'm hesitant. I'd love to pick one with fewer zeros, if anyone is willing to send one my way, I'll send it back afterward.","userId":"IzvfeUBxzWcd8VXKHq0T4MUhtQu1","displayName":"LockPickingFisherman","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.725Z","updatedAt":"2026-10-09T23:23:56.725Z"},{"id":"v_bacaafd5","type":"vote","entryId":"18ecc45b","votedBelt":"Yellow","comment":"Red Wanderer - 4 pins, spools, restrictive keyway.\\n","userId":"XoUDXU5McjTuVnPA1xfmzytcKuy2","displayName":"Red Wanderer","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.727Z","updatedAt":"2026-10-09T23:22:56.727Z"},{"id":"v_d33f7e4b","type":"vote","entryId":"18ecc45b","votedBelt":"Orange","comment":"Yagias: 5 pin core with 4 spools and 1 control.\\nCertainly harder that the Master Lock 140 and on par with an Abus 65 series","userId":"u_89015b15","displayName":"Yagias","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.727Z","updatedAt":"2026-10-09T23:23:56.727Z"},{"id":"v_b9717a3e","type":"vote","entryId":"18ecc45b","votedBelt":"Yellow","comment":"Explosion - 4 pins, spools, restrictive keyway, but very easy to set pins","userId":"XFUUNfloCTSBbNREKPDZNSRxPdq2","displayName":"Explosion","source":"Classification Sheet","createdAt":"2026-10-09T23:24:56.727Z","updatedAt":"2026-10-09T23:24:56.727Z"},{"id":"v_efcef474","type":"vote","entryId":"18ecc45b","votedBelt":"Orange","comment":"Same as many other ABUS with 4 spools and 1 regular on orange","userId":"u_3f9e3709","displayName":"Unknown","source":"Classification Sheet","createdAt":"2026-10-09T23:25:56.727Z","updatedAt":"2026-10-09T23:25:56.727Z"},{"id":"v_ec0b93be","type":"vote","entryId":"fdc8b16e","votedBelt":"Yellow","comment":"Red Wanderer - picked 3 of these. Felt like serrated pins, but navigating the tiny yale keyway even with a short hook is annoying and leads to oversets. ","userId":"XoUDXU5McjTuVnPA1xfmzytcKuy2","displayName":"Red Wanderer","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.727Z","updatedAt":"2026-10-09T23:22:56.727Z"},{"id":"v_b317783b","type":"vote","entryId":"e98dba45","votedBelt":"Purple","comment":"Hard to find some feeling at first and need a LOT of tension to open, spent 5m rechecking every discs but it was already open\\nClef","userId":"tbaq0CWuDTXerA0eUi0kGASVb1Z2","displayName":"Clefmentine","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.727Z","updatedAt":"2026-10-09T23:22:56.727Z"},{"id":"v_18a1f7b4","type":"vote","entryId":"1050a58c","votedBelt":"Orange","comment":"Very Similar to ABUS C83 with old pinning.\\nLockfumbler","userId":"gWoqbd0FOsglFD5boH96NAtJ7DE3","displayName":"LockFumbler","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.727Z","updatedAt":"2026-10-09T23:22:56.727Z"},{"id":"v_4cb274e3","type":"vote","entryId":"8182fee6","votedBelt":"Blue","comment":"Please see here for first pick https://www.youtube.com/watch?v=eKcA-ssqm0I\\n- GravityKarma","userId":"8PKfUHTiafgObsQQr162dQRlBCo1","displayName":"GravityKarma","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.727Z","updatedAt":"2026-10-09T23:22:56.727Z"},{"id":"v_0be4bca6","type":"vote","entryId":"8182fee6","votedBelt":"Blue","comment":"This is similar to Bravus 1000 without the element, also similar to XD25. \\nSame as EC880. - decoder","userId":"Mwbvdkq1QtWu2zLwEaj3imULSry1","displayName":"decoder","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.727Z","updatedAt":"2026-10-09T23:23:56.727Z"},{"id":"v_96c93ee8","type":"vote","entryId":"c24808aa","votedBelt":"White","comment":"NiXXeD\\n3 pins, one tap each.","userId":"WMSvvuutyShfvBBYB3PmDe4fmeS2","displayName":"NiXXeD","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.728Z","updatedAt":"2026-10-09T23:22:56.728Z"},{"id":"v_d9bd1690","type":"vote","entryId":"b370e57b","votedBelt":"Green","comment":"Peace: green but would require 350º pick, to pick the special pin. Else, don't think it's more than orange.","userId":"mZyfQIARjCP1uJJJc7ioMAALV9v2","displayName":"PeaceWeapon","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.728Z","updatedAt":"2026-10-09T23:22:56.728Z"},{"id":"v_81dbd1bb","type":"vote","entryId":"b370e57b","votedBelt":"Green","comment":"Same as bravus 1000 with different key tip, should be same rating with 360° requirement","userId":"u_c73d4f51","displayName":"Unknown","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.728Z","updatedAt":"2026-10-09T23:23:56.728Z"},{"id":"v_716dcb9c","type":"vote","entryId":"9ae8b650","votedBelt":"Purple","comment":"Iona\\nnot too hard but weird (wafers that act like discs, but you can pick with a hook), kinda like fontaine and others for ranking\\ncould be blue\\n","userId":"u_dded11a8","displayName":"Iona","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.787Z","updatedAt":"2026-10-09T23:22:56.787Z"},{"id":"v_7be3244f","type":"vote","entryId":"9ae8b650","votedBelt":"Orange","comment":"Lock Noob\\neasy bitting\\nhttps://discord.com/channels/140129091796992000/349621948713795594/1108796783242518588","userId":"u_c940f29e","displayName":"Lock Noob","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.787Z","updatedAt":"2026-10-09T23:23:56.787Z"},{"id":"v_1363e1bb","type":"vote","entryId":"9ae8b650","votedBelt":"Green","comment":"Unusual but not actually hard.\\ncrispix","userId":"bSkotjOGENXHGd3rpo8G3TJeCk33","displayName":"Crispix","source":"Classification Sheet","createdAt":"2026-10-09T23:24:56.787Z","updatedAt":"2026-10-09T23:24:56.787Z"},{"id":"v_bd2b9af8","type":"vote","entryId":"9ae8b650","votedBelt":"Orange","comment":"The plastic abloy Ava padlock. Flat and half round keyway version. Picked both. Both pick about the same. Half round is minimal more difficult to tension and picks slightly different due to round shape in the wafer. But that changes just pick placement. Front tension, just push the binding wafer and the core will turn with each wafer further. Pretty easy to open. Below the difficulty of spools I say even if unusual design. Orange or low green… it hurts, but I go with orange.\\n~Dig 05.03.2025","userId":"U3wCYsdGwYS8ujsO2K78iD68FMC3","displayName":"Dig","source":"Classification Sheet","createdAt":"2026-10-09T23:25:56.787Z","updatedAt":"2026-10-09T23:25:56.787Z"},{"id":"v_2df61366","type":"vote","entryId":"9ae8b650","votedBelt":"Orange","comment":"LockChuck - Not a hard pick. Just pushing the wafers from side to side until open. \\n","userId":"BuX3JAgrlzUW6Vz0L4W3YZK9iNw1","displayName":"LockChuck ","source":"Classification Sheet","createdAt":"2026-10-09T23:26:56.787Z","updatedAt":"2026-10-09T23:26:56.787Z"},{"id":"v_c42bdac0","type":"vote","entryId":"9ae8b650","votedBelt":"Orange","comment":"Wiggle wafers until it opens.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T23:27:56.787Z","updatedAt":"2026-10-09T23:27:56.787Z"},{"id":"v_f507c025","type":"vote","entryId":"8ce37fa9","votedBelt":"White","comment":"Really easy. Reasonable tension. Picked it with windshield wiper insert & Z-bar. — Marson","userId":"e2RNiz570rWqYYxDSDn6Y0uhgA43","displayName":"Marson","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.787Z","updatedAt":"2026-10-09T23:22:56.787Z"},{"id":"v_771d1648","type":"vote","entryId":"d95d6c74","votedBelt":"White","comment":"I used a 2-in-1, but could tell it was similar to the small one. — Marson","userId":"e2RNiz570rWqYYxDSDn6Y0uhgA43","displayName":"Marson","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.787Z","updatedAt":"2026-10-09T23:22:56.787Z"},{"id":"v_3a2b3e4d","type":"vote","entryId":"343d6402","votedBelt":"Blue","comment":"11 Pins (6 top, 5 bottom).  Requires rear tension and that is the only real challenge.  All standard drivers that are fairly easy to set.  Only voting blue because tensioning is a little awkward.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.787Z","updatedAt":"2026-10-09T23:22:56.787Z"},{"id":"v_fd956d77","type":"vote","entryId":"343d6402","votedBelt":"Blue","comment":"A rear tensioned 2 row pin tumbler lock. It sounds weird but is actually pretty straightforward, the challenge is setting up an suitable tension setup that does rear tension and gives good access to both rows of pins. All pins are standard without quirks, blue seems fine\\n-Dynamic","userId":"vOi8rfTRluYlcVizuVvX9PWFJdn2","displayName":"Dynamic","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.787Z","updatedAt":"2026-10-09T23:23:56.787Z"},{"id":"v_13426545","type":"vote","entryId":"5288be2f","votedBelt":"Brown","comment":"17 pins in 3 rows.  Bottom pin is just a key control pin of sorts that just needs pushed all the way down.  Decent feedback, somewhat easy to overset when keyway is cramped with low lifts.  All standard drivers, not very tapered.  Straightforward, just a lot of pins.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.787Z","updatedAt":"2026-10-09T23:22:56.787Z"},{"id":"v_527311b2","type":"vote","entryId":"02788bde","votedBelt":"Purple","comment":"13 pins.  Thin-lipped spools bite pretty hard.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.788Z","updatedAt":"2026-10-09T23:22:56.788Z"},{"id":"v_21998dc1","type":"vote","entryId":"d5080254","votedBelt":"Purple","comment":"Yagias:\\nI'd recommend same lining with Gege pExtra as it's the same lock with a different brand. ","userId":"u_89015b15","displayName":"Yagias","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.788Z","updatedAt":"2026-10-09T23:22:56.788Z"},{"id":"v_02ed722b","type":"vote","entryId":"4cd726f7","votedBelt":"Blue","comment":"6 sets of wafers (2 in a set that set together).  Leaves a lot to be desired.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.788Z","updatedAt":"2026-10-09T23:22:56.788Z"},{"id":"v_e0795ae2","type":"vote","entryId":"4cd726f7","votedBelt":"Green","comment":"Jim\\n6 pairs of wafers in dual rows. One top, middle and bottom on each side. Picks like standard pins but can overset. I only needed to pick 4 of the 6 wafers to open and several gave huge core shifts letting you know you were on the right track. ","userId":"UbhgAjZIuLauV1dw2G4QsocHIk83","displayName":"Georgia Jim","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.788Z","updatedAt":"2026-10-09T23:23:56.788Z"},{"id":"v_d546069c","type":"vote","entryId":"d60750c5","votedBelt":"Green","comment":"Jim\\nSame aptc14 core found in the 6 pin 1100’s","userId":"UbhgAjZIuLauV1dw2G4QsocHIk83","displayName":"Georgia Jim","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.788Z","updatedAt":"2026-10-09T23:22:56.788Z"},{"id":"v_e6c3b252","type":"vote","entryId":"88d5c4b4","votedBelt":"Orange","comment":"6 pins with gin type drivers without milling that basically do nothing.  \\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.788Z","updatedAt":"2026-10-09T23:22:56.788Z"},{"id":"v_825ce478","type":"vote","entryId":"88d5c4b4","votedBelt":"Orange","comment":"Zehkar","userId":"1SqcRKce18boUZBtOHWSenGAI202","displayName":"Zehkar","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.788Z","updatedAt":"2026-10-09T23:23:56.788Z"},{"id":"v_2ce86f7d","type":"vote","entryId":"c2db34fb","votedBelt":"Black 1","userId":"u_0c9fb2c1","displayName":"Unknown","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.788Z","updatedAt":"2026-10-09T23:22:56.788Z"},{"id":"v_b4e9e07a","type":"vote","entryId":"fd93632b","votedBelt":"Purple","comment":"Picks just like serrated mtl but with more muted feedback and serrations are less sharp. MGsec","userId":"GGplAdctTfVDLVvYsfIADJmfp8f2","displayName":"mgsecure","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.788Z","updatedAt":"2026-10-09T23:22:56.788Z"},{"id":"v_6b2dc322","type":"vote","entryId":"265e8045","votedBelt":"Red","comment":"6 pin, standard drivers, 5 serrated finger pins.  Basically a combi with standard drivers.  Great tolerances.  Mostly isolates but drivers can drop when setting finger pins because no false set.  \\n-Sidepicks\\n\\nhttps://imgur.com/a/assa-neptune-camlock-mPtcvIh","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.788Z","updatedAt":"2026-10-09T23:22:56.788Z"},{"id":"v_7b6b19b1","type":"vote","entryId":"265e8045","votedBelt":"Red","userId":"u_929d903a","displayName":"Unknown","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.788Z","updatedAt":"2026-10-09T23:23:56.788Z"},{"id":"v_59f9b2d7","type":"vote","entryId":"557513c8","votedBelt":"Red","comment":"significantly easier than the BB1 version with cupped standards instead of barrels/gins \\nMasterlocksux","userId":"Kvf5QQTos8OCbgr8AkULzkWjVqr1","displayName":"MasterLockSux","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.789Z","updatedAt":"2026-10-09T23:22:56.789Z"},{"id":"v_e8c8251b","type":"vote","entryId":"ce9d2399","votedBelt":"Brown","comment":"Standard cupped drivers as typical in Assa twin cam locks.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.789Z","updatedAt":"2026-10-09T23:22:56.789Z"},{"id":"v_e1db5abb","type":"vote","entryId":"4dda8329","votedBelt":"Red","comment":"Same thoughts as with 6k.  Red for either shear with possible upgrade to BB1 for both.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.789Z","updatedAt":"2026-10-09T23:22:56.789Z"},{"id":"v_48c74176","type":"vote","entryId":"c0d919e8","votedBelt":"Black 1","comment":"Trees are much easier than barrels and gins.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.789Z","updatedAt":"2026-10-09T23:22:56.789Z"},{"id":"v_eb47ede3","type":"vote","entryId":"b192d93f","votedBelt":"Purple","userId":"u_c1213e49","displayName":"Unknown","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.789Z","updatedAt":"2026-10-09T23:22:56.789Z"},{"id":"v_04c891f2","type":"vote","entryId":"e2fd1519","votedBelt":"Green","comment":"Tensioning from a disc in the middle, probably random. No false gates, muddy feedback. Tolerances aren't too good, which makes it a relatively easy pick - Greenish ","userId":"NdkmYGydSHfPTcj5xuqjwSyJJI42","displayName":"Greenish","source":"Classification Sheet","createdAt":"2026-10-04T23:22:56.789Z","updatedAt":"2026-10-04T23:22:56.789Z"},{"id":"v_e226eeb3","type":"vote","entryId":"e2fd1519","votedBelt":"Green","comment":"Seven discs and mid tension, no false gates, steady\\ncrispix","userId":"bSkotjOGENXHGd3rpo8G3TJeCk33","displayName":"Crispix","source":"Classification Sheet","createdAt":"2026-10-07T23:23:56.789Z","updatedAt":"2026-10-07T23:23:56.789Z"},{"id":"v_f0042bf3","type":"vote","entryId":"c3c7bc69","votedBelt":"Yellow","comment":"Same part number as Ace version but more difficult. Needs higher tension like Squire 440. —Marson","userId":"e2RNiz570rWqYYxDSDn6Y0uhgA43","displayName":"Marson","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.789Z","updatedAt":"2026-10-09T23:22:56.789Z"},{"id":"v_72bff588","type":"vote","entryId":"29473ee7","votedBelt":"Green","comment":"Even more difficult than the Squire 770. Getting a tensioner to stay on the talon was a pain. Needs crazy tension. I'm tempted to rate it blue, but with only 4 levers and no anti-pick, that probably won't fly. Gave me more trouble than the Fortress, Cruiser, and Insurance. — Marson","userId":"e2RNiz570rWqYYxDSDn6Y0uhgA43","displayName":"Marson","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.789Z","updatedAt":"2026-10-09T23:22:56.789Z"},{"id":"v_d5d4e6ea","type":"vote","entryId":"b68b677c","votedBelt":"Yellow","comment":"Simple little 5 pin lock that is easy to obtain in the states for sure. Think its a tad more challenging than the standard master locks, but nothing to brag about.  CajunLockPick\\n","userId":"u_fef23d37","displayName":"CajunLockPick","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.789Z","updatedAt":"2026-10-09T23:22:56.789Z"},{"id":"v_60699b17","type":"vote","entryId":"2a69b223","votedBelt":"Green","comment":"low green, side element doesn't come into play.\\n\\n-rein ","userId":"f2yySWbxUBXF8k3HgorYhrm76gx2","displayName":"Reinder","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.790Z","updatedAt":"2026-10-09T23:22:56.790Z"},{"id":"v_31493a7a","type":"vote","entryId":"2a69b223","votedBelt":"Orange","comment":"Same one Rein picked. Very straightforward. Open keyway - Greenish","userId":"NdkmYGydSHfPTcj5xuqjwSyJJI42","displayName":"Greenish","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.790Z","updatedAt":"2026-10-09T23:23:56.790Z"},{"id":"v_29a6ae7c","type":"vote","entryId":"2a69b223","votedBelt":"Green","comment":"green fits good.\\n6 pins, good tolerances, \\nThe T-pins can create a really nasty back and forth situation and need some good feeling between set and partially set pins.\\n\\nThe interactive element is set too easily and will not hinder any picking attempts in my oppinion.\\nThe Keyway is wide open which makes it easier.\\n- LockFumbler","userId":"gWoqbd0FOsglFD5boH96NAtJ7DE3","displayName":"LockFumbler","source":"Classification Sheet","createdAt":"2026-10-09T23:24:56.790Z","updatedAt":"2026-10-09T23:24:56.790Z"},{"id":"v_91609586","type":"vote","entryId":"5d5f1d87","votedBelt":"Blue","comment":"5 pin with thin-lipped mushroom spool drivers.  Requires a bit of floating after false set.  Gives deep false set.  Keyway makes it challenging to set high lifts behind low lifts.  Decoder is correct though, on paper it should be blue.\\nhttps://imgur.com/a/qMvPA7b\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.790Z","updatedAt":"2026-10-09T23:22:56.790Z"},{"id":"v_f1d7b342","type":"vote","entryId":"5d5f1d87","votedBelt":"Blue","comment":"These can be tricky to pick, but I think purple would be too high for a 5 pin tumbler. -decoder","userId":"Mwbvdkq1QtWu2zLwEaj3imULSry1","displayName":"decoder","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.790Z","updatedAt":"2026-10-09T23:23:56.790Z"},{"id":"v_7f86ecca","type":"vote","entryId":"08c823ed","votedBelt":"Black 1","comment":"LockChuck 8 Levers all with anti pick notches. Has to be picked twice to fully open. Different bitting on second pick. ","userId":"BuX3JAgrlzUW6Vz0L4W3YZK9iNw1","displayName":"LockChuck ","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.790Z","updatedAt":"2026-10-09T23:22:56.790Z"},{"id":"v_316f981d","type":"vote","entryId":"08c823ed","votedBelt":"Black 1","comment":"Borrowed LockChuck's 429. Needed fair amount of tension and patience. False gate = reset. I had to make sure any mid-lift or higher was preset. Most difficult lever lock I've picked yet, so I don't have much to compare it to. In terms of effort, it's on the border of BB1 and BB2 for me.  — Marson\\nhttps://youtu.be/_C2VW2RxWU8","userId":"e2RNiz570rWqYYxDSDn6Y0uhgA43","displayName":"Marson","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.790Z","updatedAt":"2026-10-09T23:23:56.790Z"},{"id":"v_90061cfd","type":"vote","entryId":"aa9ffc7e","votedBelt":"Black 2","comment":"Same lever and double-gate 360° throw as 428/429 but with an added sliding fence mechanism which act as a bolt blocker similar in effect to a Mersey. On mine, this also compressed and bound the lever stack. That dulled feedback but made dealing with the false gates a little easier. — Marson","userId":"e2RNiz570rWqYYxDSDn6Y0uhgA43","displayName":"Marson","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.791Z","updatedAt":"2026-10-09T23:22:56.791Z"},{"id":"v_1b9715bc","type":"vote","entryId":"e35a3c91","votedBelt":"Yellow","comment":"8 pins.  I've picked several of these now and only had to touch half the pins at most for any of them.  Some just needed two pins set.  A little hard to rank since they seem to range from white to orange roughly.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.791Z","updatedAt":"2026-10-09T23:22:56.791Z"},{"id":"v_04a828b0","type":"vote","entryId":"e35a3c91","votedBelt":"Yellow","comment":"Mine only had 1 active pin.... All the other drivers were too big to fit in the core. Ive heard of others getting ones like this too. I only say yellow because you need a flag. Kinda... Very disappointing. \\n-BurnB1","userId":"ogrEbc6fjmVOKtvfZ7vENh6oX072","displayName":"Burnetb1","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.791Z","updatedAt":"2026-10-09T23:23:56.791Z"},{"id":"v_d9353cf9","type":"vote","entryId":"e35a3c91","votedBelt":"Orange","comment":"I've picked 10 of these, pinning varies. Some had 6 active stacks, some had 5. Top row pins are passive. Some required lifting only 3 pins while others required lifting 4 or 5 and depending where you start in the lock, you might have to lift more or fewer pins. I think they're harder than yellow, probably orange, but a novice picker might pick in circles for a while. Pins are easy to overset, zero's feel like they bind the whole time. LockPickingFisherman","userId":"IzvfeUBxzWcd8VXKHq0T4MUhtQu1","displayName":"LockPickingFisherman","source":"Classification Sheet","createdAt":"2026-10-09T23:24:56.791Z","updatedAt":"2026-10-09T23:24:56.791Z"},{"id":"v_593717de","type":"vote","entryId":"e35a3c91","votedBelt":"White","comment":"Mine only has one active pin as well. I just tapped it and it opened. — Marson","userId":"e2RNiz570rWqYYxDSDn6Y0uhgA43","displayName":"Marson","source":"Classification Sheet","createdAt":"2026-10-09T23:25:56.791Z","updatedAt":"2026-10-09T23:25:56.791Z"},{"id":"v_63b0163d","type":"vote","entryId":"b1949215","votedBelt":"Black 3","comment":"tonysansan\\n\\nEven with ideal tools this is a tough pick. You have to hit the pins at an angle with a combination of pushing and rotating, which torques the core and requires delicate tension control to compensate. Unlike the door lock, you need a minimum of 6 rigid tools, and they all knock into each other and mess with the tension.","userId":"BJyWOIOsqmRDkgHZBqIEGbGnVSA3","displayName":"tonysansan","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.791Z","updatedAt":"2026-10-09T23:22:56.791Z"},{"id":"v_c4094bb6","type":"vote","entryId":"e35772c9","votedBelt":"Black 5","comment":"tonysansan\\n\\nWhile I suppose this is technically a disc detainer lock, it feels like picking a 3KS around a corner through the keyway of a chain key lock without any tension control (reverse sidebar). There is very little room to maneuver around discs and idler, and no room for error — easy to overset and have to start over.","userId":"BJyWOIOsqmRDkgHZBqIEGbGnVSA3","displayName":"tonysansan","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.791Z","updatedAt":"2026-10-09T23:22:56.791Z"},{"id":"v_00c8e65b","type":"vote","entryId":"8ea6b2be","votedBelt":"Purple","comment":"Just keep tapping.  Cam lock, picked 90 and back.  Given the current rank of some of the other pump locks, I think purple is fair.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.792Z","updatedAt":"2026-10-09T23:22:56.792Z"},{"id":"v_215d85ab","type":"vote","entryId":"8ea6b2be","votedBelt":"Purple","comment":"A tubular lock with some pin in pin action. Careful pick placement and tensioning are required. I only picked it once, but it took a few minutes to get a feel for it, so I'll call it purple. -Doc Hog","userId":"hnX373zhNoT1QZ3lc8IWVEvcz0R2","displayName":"DoctorHogmaster","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.792Z","updatedAt":"2026-10-09T23:23:56.792Z"},{"id":"v_914dae6f","type":"vote","entryId":"8ea6b2be","votedBelt":"Purple","comment":"Picks like a normal tubular lock would do, actually easier in terms of tensioning since it has the opening on the outer housing which is for the nub on the key.\\nPicking is keeping good tension and just keep tapping, pretty good feedback considering it's a tubular. Purple seems a good place.\\n-Dynamc","userId":"u_8f3c3f1b","displayName":"Unknown","source":"Classification Sheet","createdAt":"2026-10-09T23:24:56.792Z","updatedAt":"2026-10-09T23:24:56.792Z"},{"id":"v_3de4e744","type":"vote","entryId":"80a13301","votedBelt":"Purple","comment":"NiXXeD\\nMine was a 10 pin, 3 pip version. Tension is the same as a normal Ace Tubular, but there are pin-in-pin chambers. Lots and lots of tapping. Relocking at 45 degrees is interesting because the PIP chambers don't align again until 90 degrees. Even knowing what to do this took me a lot longer than Van lock to pick, but I also didn't find Van lock to be brown.\\n","userId":"WMSvvuutyShfvBBYB3PmDe4fmeS2","displayName":"NiXXeD","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.792Z","updatedAt":"2026-10-09T23:22:56.792Z"},{"id":"v_e2752118","type":"vote","entryId":"267e47c4","votedBelt":"Brown","comment":"effective anti-pick that you cant pick out of, strong springs. two06","userId":"ohnGCeCEgIOk9KzmxWcsWmGM0nM2","displayName":"7woz3ro51x","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.792Z","updatedAt":"2026-10-09T23:22:56.792Z"},{"id":"v_d9996962","type":"vote","entryId":"267e47c4","votedBelt":"Brown","comment":"Tricky anti pick features and strong springs. levers also act tapered so lot of tension needed -Greenish","userId":"NdkmYGydSHfPTcj5xuqjwSyJJI42","displayName":"Greenish","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.792Z","updatedAt":"2026-10-09T23:23:56.792Z"},{"id":"v_d007e56c","type":"vote","entryId":"dbc6670b","votedBelt":"Black 1","comment":"Lock Noob\\nhttps://discord.com/channels/140129091796992000/349621948713795594/1108796783242518588","userId":"u_c940f29e","displayName":"Lock Noob","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.792Z","updatedAt":"2026-10-09T23:22:56.792Z"},{"id":"v_47ebaea5","type":"vote","entryId":"c1c7e9d2","votedBelt":"Black 2","comment":"False gates are nasty and it's hard to avoid them.  False set means reset as does tripping the detector obviously.  3 levers with ‘active’ false gates.  Compression helps but on this one, the 6th lever has to be lifted higher than the tensioner so then there is no more compressing the lever pack. \\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.792Z","updatedAt":"2026-10-09T23:22:56.792Z"},{"id":"v_5cd89b6e","type":"vote","entryId":"0b8eeedc","votedBelt":"Brown","comment":"Somewhat tapered, good feedback.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.792Z","updatedAt":"2026-10-09T23:22:56.792Z"},{"id":"v_f6d4561b","type":"vote","entryId":"c2c1f8e0","votedBelt":"Purple","comment":"Mugatu\\nPipe key, 6 levers with false gates, good tolerances. Has another anti pick feature where a plunger effectively pushes down on the lever pack.","userId":"u_f278d262","displayName":"Mugatu","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.792Z","updatedAt":"2026-10-09T23:22:56.792Z"},{"id":"v_468ad730","type":"vote","entryId":"22d70f2e","votedBelt":"Blue","comment":"Only 5 pins but small, tight keyway and a good mix of serrated and spool pins. Crispix ","userId":"bSkotjOGENXHGd3rpo8G3TJeCk33","displayName":"Crispix","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.792Z","updatedAt":"2026-10-09T23:22:56.792Z"},{"id":"v_bd1e393e","type":"vote","entryId":"99311bb8","votedBelt":"Green","comment":"6 pin all spools, maybe one standard though.  I didn't gut.  Keyway makes max lifts slightly annoying.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.461Z"},{"id":"v_e3d79a52","type":"vote","entryId":"99311bb8","votedBelt":"Blue","comment":"NiXXeD\\nQuite difficult to get feedback. Harder than an average blue to me.","userId":"WMSvvuutyShfvBBYB3PmDe4fmeS2","displayName":"NiXXeD","source":"sheet","createdAt":"2026-10-12T23:38:02.461Z"},{"id":"v_b2c9bebf","type":"vote","entryId":"da1e5052","votedBelt":"Green","comment":"5 pins, spools, barrel, standard.  Keyway annoying for high lifts.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.462Z"},{"id":"v_321e3334","type":"vote","entryId":"da1e5052","votedBelt":"Green","comment":"LockPickingFisherman\\n1 standard, 3 spools and 1 barrel, high lifts at the back tricky to set. Springs are fairly strong, feedback is a bit muted.","userId":"IzvfeUBxzWcd8VXKHq0T4MUhtQu1","displayName":"LockPickingFisherman","source":"sheet","createdAt":"2026-10-12T23:38:02.462Z"},{"id":"v_1d37851b","type":"vote","entryId":"7e59d388","votedBelt":"Yellow","comment":"5 pin standard drivers\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.462Z"},{"id":"v_808690ed","type":"vote","entryId":"7e59d388","votedBelt":"Yellow","comment":"NiXXeD\\n","userId":"WMSvvuutyShfvBBYB3PmDe4fmeS2","displayName":"NiXXeD","source":"sheet","createdAt":"2026-10-12T23:38:02.462Z"},{"id":"v_4dc65fe6","type":"vote","entryId":"cbbe5ae1","votedBelt":"Red","comment":"16 active pins plus interactive in 5 rows.  2 passive blocker pins.  T-pin and PIP drivers (2 PIP).  Angle and spacing of pins adds to the challenge. \\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.462Z"},{"id":"v_0ef7d6ce","type":"vote","entryId":"2ae59863","votedBelt":"Brown","comment":"Not a true clone.  16 pins.  Not Clavis tolerances but very similar feeling lock.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.793Z","updatedAt":"2026-10-09T23:22:56.793Z"},{"id":"v_f91fa983","type":"vote","entryId":"2ae59863","votedBelt":"Brown","comment":"NiXXeD\\n","userId":"WMSvvuutyShfvBBYB3PmDe4fmeS2","displayName":"NiXXeD","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.793Z","updatedAt":"2026-10-09T23:23:56.793Z"},{"id":"v_832ea1f6","type":"vote","entryId":"2ae59863","votedBelt":"Brown","comment":"Close to Clavis quality. 16 pins, same lock as sidepicks.\\n-BurnB1","userId":"ogrEbc6fjmVOKtvfZ7vENh6oX072","displayName":"Burnetb1","source":"Classification Sheet","createdAt":"2026-10-09T23:24:56.793Z","updatedAt":"2026-10-09T23:24:56.793Z"},{"id":"v_62320071","type":"vote","entryId":"19bfe875","votedBelt":"Purple","comment":"7 pins plus an interactive.  Interactive is trivial but the pins are very tapered and easy to overset.  Excellent tolerances.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.463Z"},{"id":"v_9153cb00","type":"vote","entryId":"4d738de3","votedBelt":"Green","comment":"Even though on their homepage stands it should contain mushrooms I can't feel anything besides crunchy standard drivers. paracentric keyway, therefore yellow I think. \\nMoki","userId":"u_c3c19741","displayName":"Moki","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.793Z","updatedAt":"2026-10-09T23:22:56.793Z"},{"id":"v_2109d667","type":"vote","entryId":"ea00b1f8","votedBelt":"Purple","comment":"Jim \\nDual slider-sidebar design with 5 sliders per row. Deeply recessed keyway makes tensioning difficult as thicker z-bars will block the max lift sliders.  ","userId":"UbhgAjZIuLauV1dw2G4QsocHIk83","displayName":"Georgia Jim","source":"sheet","createdAt":"2026-10-12T23:37:02.463Z"},{"id":"v_17f7fb9f","type":"vote","entryId":"ea00b1f8","votedBelt":"Purple","comment":"On paper this should be purple, 10 sliders with no false gates, but I really want to rank it higher.  I struggled with this thing more than I care to admit (user error I'm sure).  That recessed keyway is challenging and tensioning can be an issue.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:38:02.463Z"},{"id":"v_a7c935e6","type":"vote","entryId":"30827d9d","votedBelt":"Blue","comment":"Jim\\n6 pins, 4 sliders same difficulty as a Yale Superior. ","userId":"UbhgAjZIuLauV1dw2G4QsocHIk83","displayName":"Georgia Jim","source":"sheet","createdAt":"2026-10-12T23:37:02.463Z"},{"id":"v_88ed1a6c","type":"vote","entryId":"30827d9d","votedBelt":"Blue","comment":"This one is just fun.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:38:02.463Z"},{"id":"v_f2ee03e1","type":"vote","entryId":"12cfd459","votedBelt":"Blue","comment":"12 sliders, 6 of them have false gates.  Somewhat resembles a dimple version of a Bilock clone.  Subtle feedback and very tapered.  You have to go back and tap everything every time you set a new slider.  Once you figure that out it opens quickly.  I was initially thinking this is probably on par with a heavily mastered Bilock but the tolerances are no where near Bilock.\\n\\nhttps://imgur.com/LUdxOmg","userId":"u_6378c921","displayName":"Unknown","source":"sheet","createdAt":"2026-10-12T23:37:02.463Z"},{"id":"v_b556fbc4","type":"vote","entryId":"c7b7c933","votedBelt":"Brown","comment":"Keyless Entry \\nSame mechanism as any Emhart with interlocking pins. Brown lock in my opinion as it contains 5 pins. 4 pins is purple and 6 pin is red/black. Fits nicely in between at brown. ","userId":"u_a40e1c1a","displayName":"Keyless Entry","source":"sheet","createdAt":"2026-10-12T23:37:02.464Z"},{"id":"v_d08a2425","type":"vote","entryId":"c7b7c933","votedBelt":"Brown","comment":"5 pin euro format (not cam lock).\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:38:02.464Z"},{"id":"v_795862d0","type":"vote","entryId":"2693d016","votedBelt":"Purple","comment":"6 pin, one master on 4.  Stacks 2 and 3 are standard drivers that interact with control sleeve.  I’d say maybe brown if picked to operating and control but not sure that really makes it much harder.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.464Z"},{"id":"v_5b1dd64f","type":"vote","entryId":"327ad74d","votedBelt":"Green","comment":"LockFubmler:\\nNice Security pins, but in mine the tolerances felt quite broad and it was very easy to set. might even be orange, but green feels good.","userId":"gWoqbd0FOsglFD5boH96NAtJ7DE3","displayName":"LockFumbler","source":"sheet","createdAt":"2026-10-12T23:37:02.464Z"},{"id":"v_4a19675a","type":"vote","entryId":"d5f5ab98","votedBelt":"Blue","comment":"6 pins, standards and spools.  Felt same as EPS.  Same sidebar present as in EPS but trap did not engage when 360'd.  Felt green so it could go either way.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.464Z"},{"id":"v_1302dbb5","type":"vote","entryId":"d4f98a26","votedBelt":"Blue","comment":"5 pins, spools and standards.  Keyway and bitting made this one particularly difficult.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.464Z"},{"id":"v_ac27c383","type":"vote","entryId":"8aeb75bf","votedBelt":"Blue","comment":"5 pin tumblers with 4 side dimple pins.  Very stiff spring requires heavy tension to bind pins.  Low lift side dimples get in the way of picking the pin tumblers.  Pin tumblers are very crunchy which dampens feedback.  Lock is not guttable but felt like serrated drivers.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.464Z"},{"id":"v_1dcc13f9","type":"vote","entryId":"8aeb75bf","votedBelt":"Blue","comment":"Jim\\n\\nGoing with blue simply for the number of elements and dual locking mechanisms. Mine felt greenish picking wise but I don’t think there’s anything at green that’s comparable. ","userId":"NdkmYGydSHfPTcj5xuqjwSyJJI42","displayName":"Greenish","source":"sheet","createdAt":"2026-10-12T23:38:02.464Z"},{"id":"v_bf0af1ee","type":"vote","entryId":"da202edb","votedBelt":"Blue","comment":"Peace: opposing pins, springs are not strong enough for oversetting most time or are easy to get set by pulsing tension. Still a good challenge. Easy-ish blue.","userId":"mZyfQIARjCP1uJJJc7ioMAALV9v2","displayName":"PeaceWeapon","source":"sheet","createdAt":"2026-10-12T23:37:02.464Z"},{"id":"v_3f1a6fe3","type":"vote","entryId":"6752c748","votedBelt":"Brown","comment":"It's hard because it's janky.  The levers bind against each other and the guides and when they break free they like to jump the gate.  When they overset the spring doesn't always (or usually) push them back down.  A lot of times you have to reset and jiggle key to get them to drop.  The ones that do drop are very tapered.  \\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.464Z"},{"id":"v_7039d866","type":"vote","entryId":"0f9616db","votedBelt":"Orange","comment":"I think low Orange, there are 6 standard pins and while its nicely constructed (possibly an American 1100 style core?), the feedback can be a bit mute. I could also be sold for high yellow on this lock.\\n~Bugasu\\n","userId":"qtp7IM8d9sawUEAKsM0vwMITexR2","displayName":"Bugasu","source":"sheet","createdAt":"2026-10-12T23:37:02.465Z"},{"id":"v_e80d5c89","type":"vote","entryId":"0f9616db","votedBelt":"Orange","comment":"all standard pins,  fun responsive pick purchased through Max1K GB (spy-c)","userId":"VBmk1eBTsyeE3MqvDJMRrWoM3mt1","displayName":"Spyc","source":"sheet","createdAt":"2026-10-12T23:38:02.465Z"},{"id":"v_ef578086","type":"vote","entryId":"955dbd20","votedBelt":"Black 5","comment":"tonysansan\\n\\nSignificantly harder than interior. Blocker is unpredictable, locking some levers in place from the start, and causing trouble for other levers throughout picking. Requires precise tensioning, differentiating feedback from both blocker and gates, and working some levers in pairs. Solid BB5.","userId":"BJyWOIOsqmRDkgHZBqIEGbGnVSA3","displayName":"tonysansan","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.795Z","updatedAt":"2026-10-09T23:22:56.795Z"},{"id":"v_13dff22d","type":"vote","entryId":"fef612a9","votedBelt":"Blue","comment":"5 pins plus an interactive that encompasses pin one.  Sometimes the interactive didn't engage.  Keyway and bitting was the main challenge with this lock.  Low blue.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.465Z"},{"id":"v_7ad03da0","type":"vote","entryId":"a46da1af","votedBelt":"Orange","comment":"Annoying to tension, have to have a Y tension tool or swap sides a few times. Awkward","userId":"u_4bd051ff","displayName":"Unknown","source":"sheet","createdAt":"2026-10-12T23:37:02.465Z"},{"id":"v_7f7e84d0","type":"vote","entryId":"89207b78","votedBelt":"Brown","comment":"82 Deadlock.  5 levers, false gates, strong springs.  \\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.795Z","updatedAt":"2026-10-09T23:22:56.795Z"},{"id":"v_745b6e94","type":"vote","entryId":"a7b71b37","votedBelt":"Brown","comment":"Harder than an Anchor Las but a little easier than an Abus Plus,\\n\\nZero cut discs settle past zero much like the butterfly discs in an Abus Plus and also the disc pack is spring compressed again like an Abus. Both of these factors combine to reduce feedback greatly.\\n\\nfeedback is very muted until some of the discs are located in gates, this can be improved a little by tilting the pick to drive the discs into the sidebar \\n\\nIt does have a dedicated tensioning disc in position 8 that avoids the need to counter rotate to get the open \\n\\nYou also have to make or modify a tool, there is nothing commercially available for this lock\\n\\nThese reasons are why I feel a brown is the best fit \\n\\nLock Picking Paul\\n","userId":"SyjMMYh9rYPI0lrxAWu5z5rrawx2","displayName":"Lock Picking Paul","source":"sheet","createdAt":"2026-10-12T23:37:02.465Z"},{"id":"v_fe5db291","type":"vote","entryId":"cd5acff8","votedBelt":"Orange","comment":"mgsecure\\n\\n6-pin dimple with two spools. Available at UHS hardware, one of the few dimple options in the US","userId":"GGplAdctTfVDLVvYsfIADJmfp8f2","displayName":"mgsecure","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.796Z","updatedAt":"2026-10-09T23:22:56.796Z"},{"id":"v_bd6af401","type":"vote","entryId":"48e2c276","votedBelt":"Blue","comment":"No false gates, but mine required rear tension/random mid tension so I think this fits at blue \\n-Joey","userId":"BlQBaytglSfa2ExVbvg4itQPrbB2","displayName":"Joey","source":"sheet","createdAt":"2026-10-12T23:37:02.465Z"},{"id":"v_5c2a0c90","type":"vote","entryId":"415b46ca","votedBelt":"Green","comment":"3 rows with 14 pins but only the bottom row of 6 pins are active so it's essentially just a 6-pin dimple lock with a huge keyway.  Mix of standards and spools.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.466Z"},{"id":"v_43065435","type":"vote","entryId":"89af3f11","votedBelt":"Orange","comment":"Very good tolerances.  Easy to overset.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.466Z"},{"id":"v_cf98aa76","type":"vote","entryId":"df1c9fe9","votedBelt":"Blue","comment":"Somewhat tapered levers, still good feedback even with compression.  Need curtained wire pick.  No false gates.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.466Z"},{"id":"v_e860a59c","type":"vote","entryId":"df1c9fe9","votedBelt":"Red","comment":"I found mine insanely difficult for something w/o false gates. The Walsall 2000 (brown) and WLN Detector (red) were much easier for me. I could not get more than a few levers to stay up without compression, and with compression it was easy to overset. Once I got the compression just right, it popped quickly. I may just suck at 3D tension and finding the right balance. — Marson","userId":"e2RNiz570rWqYYxDSDn6Y0uhgA43","displayName":"Marson","source":"sheet","createdAt":"2026-10-12T23:38:02.466Z"},{"id":"v_a5526896","type":"vote","entryId":"cc2c31c5","votedBelt":"Blue","comment":"8 levers no false gates.  Somewhat tapered, good feedback.  Very similar to 7 lever except you don't need a curtained wire pick.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.466Z"},{"id":"v_176b02e6","type":"vote","entryId":"93324d19","votedBelt":"Blue","comment":"Mugatu\\nAwkward to tension, tensioning after the first 1/4 core lockup becomes an issue. All standard pins, did not act taper.\\nI'd say blue for the initial picked open position but could well see it purple for a full 360 given the tensioning complication.","userId":"u_f278d262","displayName":"Mugatu","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.796Z","updatedAt":"2026-10-09T23:22:56.796Z"},{"id":"v_4f1587c9","type":"vote","entryId":"352d0624","votedBelt":"Purple","comment":"clef\\nmaybe easy purple but i think hard blue.\\npassives pins on top align at 180° and you need to pick them to finish rotation","userId":"tbaq0CWuDTXerA0eUi0kGASVb1Z2","displayName":"Clefmentine","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.797Z","updatedAt":"2026-10-09T23:22:56.797Z"},{"id":"v_ace57f78","type":"vote","entryId":"352d0624","votedBelt":"Blue","comment":"Jim","userId":"UbhgAjZIuLauV1dw2G4QsocHIk83","displayName":"Georgia Jim","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.797Z","updatedAt":"2026-10-09T23:23:56.797Z"},{"id":"v_92e3cf20","type":"vote","entryId":"352d0624","votedBelt":"Purple","comment":"easy purple IMO, still harder than most blue dimple locks I've picked \\n-DQ","userId":"qXhqtUdEVFfrajxqblKl8bqQqXM2","displayName":"DQ","source":"Classification Sheet","createdAt":"2026-10-09T23:24:56.797Z","updatedAt":"2026-10-09T23:24:56.797Z"},{"id":"v_2eaca237","type":"vote","entryId":"352d0624","votedBelt":"Purple","comment":"Really fun pick. The 360 really adds a good challenge. Mine has what appears to be barbell like pins and the ends are tiny spools. Purple sounds good. I wouldn't recommend this to someone looking for a blue lock. \\n-Nightmare","userId":"kBjhBaserkb0dTYBtgzNcLddnyy1","displayName":"Nightmare","source":"Classification Sheet","createdAt":"2026-10-09T23:25:56.797Z","updatedAt":"2026-10-09T23:25:56.797Z"},{"id":"v_54054f72","type":"vote","entryId":"81ecb2e7","votedBelt":"Black 4","comment":"tonysansan\\n\\nRequires extreme tension, and otherwise reminds me a bit of 6K174. Heavily tapered and traps on both sides of every lever. It is possible to float pick out of the near-side traps.","userId":"BJyWOIOsqmRDkgHZBqIEGbGnVSA3","displayName":"tonysansan","source":"sheet","createdAt":"2026-10-12T23:37:02.466Z"},{"id":"v_7edfd5a6","type":"vote","entryId":"81c91d86","votedBelt":"Green","comment":"Reinder's lock. Pretty straightforward, post makes tensioning awkward - Greenis","userId":"f2yySWbxUBXF8k3HgorYhrm76gx2","displayName":"Reinder","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.797Z","updatedAt":"2026-10-09T23:22:56.797Z"},{"id":"v_ae2bbe6d","type":"vote","entryId":"476995cc","votedBelt":"Brown","comment":"6 levers.  I didn't gut but I didn't feel any false gates.  Pretty tricky lock for no false gates.  Very tapered and lever bind very hard.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.797Z","updatedAt":"2026-10-09T23:22:56.797Z"},{"id":"v_4447d80e","type":"vote","entryId":"97e1ae9f","votedBelt":"Black 1","comment":"CK (with standard drivers)","userId":"u_a970b935","displayName":"CK","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.797Z","updatedAt":"2026-10-09T23:22:56.797Z"},{"id":"v_c3ac34ee","type":"vote","entryId":"ca9828d7","votedBelt":"Brown","comment":"Jim\\nSlightly harder than TK5 with smooth fingers. Smooth sidebar with chamfering on the edges makes rotating serrated finger pins easier than even a smooth sidebar with 90° angles. Nowhere near black, and probably brown as both regular and 29sl primus are harder. ","userId":"UbhgAjZIuLauV1dw2G4QsocHIk83","displayName":"Georgia Jim","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.797Z","updatedAt":"2026-10-09T23:22:56.797Z"},{"id":"v_ce1be3a5","type":"vote","entryId":"ca9828d7","votedBelt":"Red","comment":"yabende\\nMore difficult than TK5 and easier than SK6 Sperwelle Extra Code. In my opinion, red is fair","userId":"Gg9KxwHOwBf03QAIdOgZbfW3hRo1","displayName":"yabende","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.797Z","updatedAt":"2026-10-09T23:23:56.797Z"},{"id":"v_1ce9058e","type":"vote","entryId":"ca9828d7","votedBelt":"Brown","comment":"easier than the tk5 with serrated fingerpins, felt about as hard as the smooth ones and the extra pin did not do anything for the tops\\n-Alpama","userId":"FGhShmNkxTXC9vwmZwWylOvU8K72","displayName":"Alpama","source":"Classification Sheet","createdAt":"2026-10-09T23:24:56.797Z","updatedAt":"2026-10-09T23:24:56.797Z"},{"id":"v_a4817c75","type":"vote","entryId":"ca9828d7","votedBelt":"Red","comment":"Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T23:25:56.797Z","updatedAt":"2026-10-09T23:25:56.797Z"},{"id":"v_a21738fe","type":"vote","entryId":"ca9828d7","votedBelt":"Red","comment":"Zehkar","userId":"1SqcRKce18boUZBtOHWSenGAI202","displayName":"Zehkar","source":"sheet","createdAt":"2026-10-12T23:41:02.467Z"},{"id":"v_04a658e0","type":"vote","entryId":"3184aca4","votedBelt":"Blue","comment":"Marson\\nMuch like the Miwa DS\\nhttps://www.youtube.com/watch?v=_Iu7u6Mp4j8","userId":"e2RNiz570rWqYYxDSDn6Y0uhgA43","displayName":"Marson","source":"sheet","createdAt":"2026-10-12T23:37:02.467Z"},{"id":"v_3779441a","type":"vote","entryId":"8d4632d9","votedBelt":"Blue","comment":"peace: similar to tubar, a little harder than fontaine except you don't need to 360°. Don't need special tensioner but it can obstruct a bit","userId":"mZyfQIARjCP1uJJJc7ioMAALV9v2","displayName":"PeaceWeapon","source":"Classification Sheet","createdAt":"2026-10-08T23:22:56.798Z","updatedAt":"2026-10-08T23:22:56.798Z"},{"id":"v_872e76a9","type":"vote","entryId":"8d4632d9","votedBelt":"Purple","comment":"sameline with tubar because its a tubar\\n\\n-rein ","userId":"f2yySWbxUBXF8k3HgorYhrm76gx2","displayName":"Reinder","source":"Classification Sheet","createdAt":"2026-10-07T22:49:56.798Z","updatedAt":"2026-10-08T22:49:56.798Z"},{"id":"v_1172e76aaa","type":"vote","entryId":"8d4632d9","votedBelt":"Purple","comment":"It's another modern vote","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-10T22:49:56.798Z","updatedAt":"2026-10-10T22:49:56.798Z"},{"id":"v_05063f2b","type":"vote","entryId":"22f4aa06","votedBelt":"Orange","comment":"NiXXeD\\nSpools","userId":"WMSvvuutyShfvBBYB3PmDe4fmeS2","displayName":"NiXXeD","source":"sheet","createdAt":"2026-10-12T23:37:02.468Z"},{"id":"v_65a3ecf8","type":"vote","entryId":"fe305753","votedBelt":"Purple","comment":"top row contain active pin quite hard to set cause of no lift bottom row\\n\\nclef","userId":"tbaq0CWuDTXerA0eUi0kGASVb1Z2","displayName":"Clefmentine","source":"sheet","createdAt":"2026-10-12T23:37:02.468Z"},{"id":"v_99991cd8","type":"vote","entryId":"6d6f1e8e","votedBelt":"Blue","comment":"These are just nasty but nobody knows why xD we had lots of trouble with these at LockCon - decoder","userId":"Mwbvdkq1QtWu2zLwEaj3imULSry1","displayName":"decoder","source":"sheet","createdAt":"2026-10-12T23:37:02.468Z"},{"id":"v_e3e54e80","type":"vote","entryId":"6d6f1e8e","votedBelt":"Blue","comment":"Only one spool, but somehow it is quite difficult. It reminds me somewhat of the NEMEF NF2, but less security pins. Pretty good tolerance.\\n- LockFumbler","userId":"gWoqbd0FOsglFD5boH96NAtJ7DE3","displayName":"LockFumbler","source":"sheet","createdAt":"2026-10-12T23:38:02.468Z"},{"id":"v_891d1a4e","type":"vote","entryId":"73f7dfee","votedBelt":"Purple","comment":"16 pins (all standard drivers) in 4 rows oriented similar to Kaba experT.  It actually has pretty good tolerances, there is almost no core movement which causes it to be slightly tapered.  The warding plays a minor role for max lifts.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.468Z"},{"id":"v_f8df371b","type":"vote","entryId":"a7d98df3","votedBelt":"Red","comment":"I have a 15 pin variant and this thing is brutal, conservative red till other examples pop up. this is harder than most 20s I've picked.\\n-GravityKarma\\n ","userId":"8PKfUHTiafgObsQQr162dQRlBCo1","displayName":"GravityKarma","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.798Z","updatedAt":"2026-10-09T23:22:56.798Z"},{"id":"v_07d66bde","type":"vote","entryId":"f97ad477","votedBelt":"Purple","comment":"12 pins in the lock I picked. Felt slightly tapered as little taps would give some core movement. Had to pick CW because cam. \\n\\n-Nightmare","userId":"kBjhBaserkb0dTYBtgzNcLddnyy1","displayName":"Nightmare","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.798Z","updatedAt":"2026-10-09T23:22:56.798Z"},{"id":"v_a0543de2","type":"vote","entryId":"a0ff6aab","votedBelt":"Brown","comment":"yabende \\n14 pins in 3 rows, all pins tapered standards - easy to get an overset","userId":"Gg9KxwHOwBf03QAIdOgZbfW3hRo1","displayName":"yabende","source":"sheet","createdAt":"2026-10-12T23:37:02.468Z"},{"id":"v_1d11f8e4","type":"vote","entryId":"a0ff6aab","votedBelt":"Brown","comment":"+1 to Yabende\\nPlz7\\n","userId":"qOSRbnEHbjcbQ7pT31Omv16R0NI3","displayName":"Plz7 ","source":"sheet","createdAt":"2026-10-12T23:38:02.468Z"},{"id":"v_02bd95a4","type":"vote","entryId":"93a685a3","votedBelt":"Purple","comment":"Could be blue maybe.  Easy to overset.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.468Z"},{"id":"v_8472e43d","type":"vote","entryId":"c6d7338d","votedBelt":"Blue","comment":"Weird shackle design.  Lock opens CCW.  12 directly opposing pins.  Not guttable.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.469Z"},{"id":"v_8926370e","type":"vote","entryId":"c6d7338d","votedBelt":"Blue","comment":"I don't see the point of ranking this, since no other examples of this lock have been found yet. So we are basically ranking this one specific lock, which doesn't warrant an entry in the belt list for me. \\n-BurnB1","userId":"ogrEbc6fjmVOKtvfZ7vENh6oX072","displayName":"Burnetb1","source":"sheet","createdAt":"2026-10-12T23:38:02.469Z"},{"id":"v_9ba0b7d5","type":"vote","entryId":"fe9889e2","votedBelt":"Red","comment":"yabende\\n14 pins. Poor feedback and some weird pins - the keypin has a dimple in the base and the driver pin is convex, like a half sphere - quite problematic positioning with disturbed feedback","userId":"Gg9KxwHOwBf03QAIdOgZbfW3hRo1","displayName":"yabende","source":"Classification Sheet","createdAt":"2026-10-07T23:22:56.799Z","updatedAt":"2026-10-07T23:22:56.799Z"},{"id":"v_6b38f945","type":"vote","entryId":"fe9889e2","votedBelt":"Red","userId":"u_46dcae62","displayName":"Unknown","source":"Classification Sheet","createdAt":"2026-10-07T23:23:56.799Z","updatedAt":"2026-10-07T23:23:56.799Z"},{"id":"v_6cd72554","type":"vote","entryId":"991c6c07","votedBelt":"Purple","comment":"A bit harder then 29a/b. Not by a lot IMHO -Retep","userId":"u_7e351cf1","displayName":"Retep","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.799Z","updatedAt":"2026-10-09T23:22:56.799Z"},{"id":"v_12edeb62","type":"vote","entryId":"ad6a971b","votedBelt":"Green","comment":"Red Wanderer - This version of the kodai has no milling and sort of t pins rather than gin spools. Pretty easy.","userId":"XoUDXU5McjTuVnPA1xfmzytcKuy2","displayName":"Red Wanderer","source":"sheet","createdAt":"2026-10-12T23:37:02.469Z"},{"id":"v_d7abecc9","type":"vote","entryId":"c65959a3","votedBelt":"Purple","comment":"Primary feedback is audio.  Bit of trial and error figuring out true and false gates but gets a little easier as you get more wheels in true gates.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.799Z","updatedAt":"2026-10-09T23:22:56.799Z"},{"id":"v_c95603e4","type":"vote","entryId":"5ebb1bae","votedBelt":"Purple","comment":"8 Discs plus front gated spinner.  0 cut (max rotation) discs don't have false gates all others have two false gates.  Requires rear tension but I was able to make front tension work on this particular lock.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.469Z"},{"id":"v_365f226a","type":"vote","entryId":"5ebb1bae","votedBelt":"Purple","comment":"Jim\\nPicks very similar to Anchor Las, just with 8 discs vs 11 in the anchor. False gates lock up super hard and require releasing all tension to get the discs to move.","userId":"UbhgAjZIuLauV1dw2G4QsocHIk83","displayName":"Georgia Jim","source":"sheet","createdAt":"2026-10-12T23:38:02.469Z"},{"id":"v_c51ae516","type":"vote","entryId":"4dad61fd","votedBelt":"Purple","comment":"2 rows of 5 pins, some torpedo key pins and some mushroom drivers. Good tolerances, well made, for how tiny it is this lock puts up a fight.\\nI feel like it's on par, or even a little harder than the Clavis 10 pin.\\nPlz7 ","userId":"qOSRbnEHbjcbQ7pT31Omv16R0NI3","displayName":"Plz7 ","source":"sheet","createdAt":"2026-10-12T23:37:02.469Z"},{"id":"v_f2b095cc","type":"vote","entryId":"4dad61fd","votedBelt":"Purple","comment":"Very well made little lock, good tolerances and clear feedback, standards pins mixed with spools, gives nice false set and counter rotation. Requires delicate picking cause it’s easy to overset low lifts. Definitely purple \\nSiedem50","userId":"zknSa6jFFBhBQgQ1sKU4V5afbUi2","displayName":"Siedem50","source":"sheet","createdAt":"2026-10-12T23:38:02.469Z"},{"id":"v_c99bd668","type":"vote","entryId":"64662298","votedBelt":"Green","comment":"clef\\nno anti pick just 7 pins\\nall side pins do not have to be touched for picking.\\nusually mastered","userId":"tbaq0CWuDTXerA0eUi0kGASVb1Z2","displayName":"Clefmentine","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.800Z","updatedAt":"2026-10-09T23:22:56.800Z"},{"id":"v_dca1b93c","type":"vote","entryId":"64662298","votedBelt":"Green","userId":"u_554ac50f","displayName":"Unknown","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.800Z","updatedAt":"2026-10-09T23:23:56.800Z"},{"id":"v_40196e41","type":"vote","entryId":"2070725d","votedBelt":"Purple","comment":"I assume this is a Rols just with 5 pins.  Looks exactly like a Rols.  Tapered as with most push/pump locks.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.470Z"},{"id":"v_9e577284","type":"vote","entryId":"8e11009a","votedBelt":"Blue","comment":"clef\\n5 pin dimple lock 2 barrels and 3 spools.\\nthe picking is not hard you just need to be carefull to not set the alarm.\\nalarm is trigered by vibration on pushing the pin inside the cam","userId":"tbaq0CWuDTXerA0eUi0kGASVb1Z2","displayName":"Clefmentine","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.800Z","updatedAt":"2026-10-09T23:22:56.800Z"},{"id":"v_1988d2d5","type":"vote","entryId":"1dd55e66","votedBelt":"Brown","comment":"Interesting lock. 7 security drivers and also security keypins which are all tapered a bit + additional 4 slider wafer combined with 6 sidebar pins whereas 5 of them interact each with the slider wafer in overlapping type. \\nI found the feedback of the mainpins far away from easy to tell the state and also the slider wafers are kinda interesting if picked one by one.\\nA lot of ping pong like with tapers because of the interaction of the slider wafers and the sidebar pins. \\nYeah I had to invent new words for that 😅 I think with my pinning it can’t be on the same level as milenco magnum and all those other locks on purple. So I judge it to be brown belt. There is a flaw about depending on the slider wafers bitting to full lift all might work to open the lock after picking the main pins. \\n\\nSee video for better understanding. \\n\\nhttps://youtu.be/2licUMd_zb0?si=MnShQN_Vu1hRrsON\\n\\nThanks,  ~ Dig 09.12.2025","userId":"U3wCYsdGwYS8ujsO2K78iD68FMC3","displayName":"Dig","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.800Z","updatedAt":"2026-10-09T23:22:56.800Z"},{"id":"v_7f853413","type":"vote","entryId":"8587f825","votedBelt":"Yellow","comment":"5 pin (drilled for 6) all standard cupped drivers.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.470Z"},{"id":"v_7ddde376","type":"vote","entryId":"8587f825","votedBelt":"Orange","comment":"NiXXeD\\nHad some easy picks of this but confusing feedback sometimes.","userId":"WMSvvuutyShfvBBYB3PmDe4fmeS2","displayName":"NiXXeD","source":"sheet","createdAt":"2026-10-12T23:38:02.470Z"},{"id":"v_600e6d73","type":"vote","entryId":"c8dd4973","votedBelt":"Orange","comment":"5 pins (2 spools, 3 standards), 2 passive side pins.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.470Z"},{"id":"v_4db81b08","type":"vote","entryId":"0f23f119","votedBelt":"Blue","comment":"5 standard pins, no milling, pretty straightforward blue pin in pin lock\\nPlz7 ","userId":"qOSRbnEHbjcbQ7pT31Omv16R0NI3","displayName":"Plz7 ","source":"sheet","createdAt":"2026-10-12T23:37:02.470Z"},{"id":"v_d481d56b","type":"vote","entryId":"2ab8a900","votedBelt":"Blue","comment":"NiXXeD\\nSept's lock. Easier blue. Not as hard as trioving, but dimple. This was an easier bitting, so I imagine better bittings would dip into harder blue.","userId":"u_eb7a8217","displayName":"SeptClues","source":"sheet","createdAt":"2026-10-12T23:37:02.470Z"},{"id":"v_a6a9017e","type":"vote","entryId":"2ab8a900","votedBelt":"Blue","comment":"Wyte\\nHe's too lazy to type here but he said it in discord here: https://discord.com/channels/140129091796992000/140129091796992000/1314371561637150922","userId":"SW6Z2ZqK2JZqdOdcJZYf0vj1QPj1","displayName":"Wyte","source":"sheet","createdAt":"2026-10-12T23:38:02.470Z"},{"id":"v_609a8cd1","type":"vote","entryId":"45bb95df","votedBelt":"Red","comment":"Same as the base codkey locksys 15 pinner but one of the chambers is replaced with steel pin that's sprug outwards of the core. The warding makes it very difficult to position the magnet on the right spot and for me it didn't work to put it at the end when everything else was picked. Defiently harder than the base codkey wich is rated brown so I'll give this one red, not sure if it deserves bb1 \\n-DQ ","userId":"qXhqtUdEVFfrajxqblKl8bqQqXM2","displayName":"DQ","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.801Z","updatedAt":"2026-10-09T23:22:56.801Z"},{"id":"v_65c6b280","type":"vote","entryId":"45bb95df","votedBelt":"Red","comment":"Red IMO\\nyabende","userId":"Gg9KxwHOwBf03QAIdOgZbfW3hRo1","displayName":"yabende","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.801Z","updatedAt":"2026-10-09T23:23:56.801Z"},{"id":"v_927d82ae","type":"vote","entryId":"45bb95df","votedBelt":"Brown","comment":"the magnetic element is negligible imo, get a magnet in there and pick like normal \\n\\n-rein","userId":"f2yySWbxUBXF8k3HgorYhrm76gx2","displayName":"Reinder","source":"Classification Sheet","createdAt":"2026-10-09T23:24:56.801Z","updatedAt":"2026-10-09T23:24:56.801Z"},{"id":"v_85f3627b","type":"vote","entryId":"61a58865","votedBelt":"Green","comment":"Nice intro dimple lock.\\n-Sidepicks\\n\\nhttps://imgur.com/a/lucznik-ep-2R6ld8o","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.471Z"},{"id":"v_03d601fa","type":"vote","entryId":"3440f169","votedBelt":"Red","comment":"Very careful tension control required. A very unique magnetic lock\\n- DND","userId":"XKPQaAR525XV2JsqGn12eEKwxD62","displayName":"DoNotDuplicate","source":"sheet","createdAt":"2026-10-12T23:37:02.471Z"},{"id":"v_d044041b","type":"vote","entryId":"3440f169","votedBelt":"Red","comment":"3-rotor cam lock version. Tension is ass, could see this being BB in harder examples. - two06","userId":"ohnGCeCEgIOk9KzmxWcsWmGM0nM2","displayName":"7woz3ro51x","source":"sheet","createdAt":"2026-10-12T23:38:02.471Z"},{"id":"v_8de770d9","type":"vote","entryId":"9a2ebc39","votedBelt":"Blue","comment":"Could be green maybe.  Feedback a little weird.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.471Z"},{"id":"v_5e2aee21","type":"vote","entryId":"9a2ebc39","votedBelt":"Blue","comment":"Jim\\n\\nBlue is a fair imo. Found it more difficult than common blue dimple locks. The key pins are spike shaped which can make keeping your pick on them difficult, especially max lifts. I only felt two spools when picking, 7 pins total. ","userId":"UbhgAjZIuLauV1dw2G4QsocHIk83","displayName":"Georgia Jim","source":"sheet","createdAt":"2026-10-12T23:38:02.471Z"},{"id":"v_609df7b6","type":"vote","entryId":"2e4aa386","votedBelt":"Blue","comment":"4 top pins and 5 side wafers.  Typical Magnum tolerances.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.471Z"},{"id":"v_3c169c6e","type":"vote","entryId":"f74e0e97","votedBelt":"Brown","comment":"comes pinned with standards but picked to both shears along with the sliders it's not the easiest.\\n(note, i picked it with m2 pins)\\n-rein","userId":"f2yySWbxUBXF8k3HgorYhrm76gx2","displayName":"Reinder","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.801Z","updatedAt":"2026-10-09T23:22:56.801Z"},{"id":"v_48d75f86","type":"vote","entryId":"f74e0e97","votedBelt":"Brown","userId":"u_8ba6e7b8","displayName":"Unknown","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.801Z","updatedAt":"2026-10-09T23:23:56.801Z"},{"id":"v_54fab524","type":"vote","entryId":"f66156e6","votedBelt":"Yellow","comment":"5 pin, only standard drivers in mine, I gutted it to be sure. Tis doesn't feel orange to me, it's not on the same level as Abus 55/40, which feels solid orange. LockPickingFisherman","userId":"IzvfeUBxzWcd8VXKHq0T4MUhtQu1","displayName":"LockPickingFisherman","source":"sheet","createdAt":"2026-10-12T23:37:02.472Z"},{"id":"v_7aeb5bac","type":"vote","entryId":"a6f31065","votedBelt":"Orange","comment":"Peace: 6 pins, spools, good orange pick","userId":"mZyfQIARjCP1uJJJc7ioMAALV9v2","displayName":"PeaceWeapon","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.801Z","updatedAt":"2026-10-09T23:22:56.801Z"},{"id":"v_0e816e74","type":"vote","entryId":"a6f31065","votedBelt":"Orange","comment":"LockPickingFisherman\\nEssentially the same as Master 1145, in a different body. 5 spools,  serrated in chamber 1. Same fairly open keyway. 1145 and 2950EURD could be samelined imo. Both are fun, good intro's to dimples.","userId":"IzvfeUBxzWcd8VXKHq0T4MUhtQu1","displayName":"LockPickingFisherman","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.801Z","updatedAt":"2026-10-09T23:23:56.801Z"},{"id":"v_bf11d9bb","type":"vote","entryId":"f55a1ed1","votedBelt":"Blue","comment":"did a full breakdown video - https://youtu.be/FPR_MFSZJ08?si=nx6x99LSGM9mHt5U\\nbut in short summary I believe it deserves blue belt - has great tolerances and the interractive works with the spools making you go and set them several times - first all the spools, then the interractive, then the spools again\\n-DQ","userId":"qXhqtUdEVFfrajxqblKl8bqQqXM2","displayName":"DQ","source":"sheet","createdAt":"2026-10-12T23:37:02.472Z"},{"id":"v_aeb0c948","type":"vote","entryId":"62bffe18","votedBelt":"Purple","comment":"Top pins (if picked Euro style) are finicky and easy to overset.  Spools are effective and caused other pins to drop every time.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.472Z"},{"id":"v_80dbf1b2","type":"vote","entryId":"62bffe18","votedBelt":"Purple","comment":"NiXXeD\\nSame lock as sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:38:02.472Z"},{"id":"v_eccc9b12","type":"vote","entryId":"e79f0f35","votedBelt":"Orange","comment":"peace: main stack a bit tapered but not as hard as some TESAs, opposing stack made of key control sprung pins, when 180ò they will trap the core, need to pick them one by one. After picking a couple farder orange, maybe an easy green, but only if 360º","userId":"mZyfQIARjCP1uJJJc7ioMAALV9v2","displayName":"PeaceWeapon","source":"sheet","createdAt":"2026-10-12T23:37:02.472Z"},{"id":"v_a1925b4a","type":"vote","entryId":"e79f0f35","votedBelt":"Orange","userId":"u_8aa85275","displayName":"Unknown","source":"sheet","createdAt":"2026-10-12T23:38:02.472Z"},{"id":"v_c223fc56","type":"vote","entryId":"a2acb3c9","votedBelt":"Purple","comment":"Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.472Z"},{"id":"v_5cae2ec2","type":"vote","entryId":"52d0964d","votedBelt":"Green","comment":"Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.472Z"},{"id":"v_118abb56","type":"vote","entryId":"ad46dc5a","votedBelt":"Brown","comment":"Skwiggledork https://discord.com/channels/140129091796992000/349621948713795594/1242980065067925574","userId":"zDpOLv3IAPSdIwPpSPGf8cKQumx2","displayName":"Skwiggs","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.802Z","updatedAt":"2026-10-09T23:22:56.802Z"},{"id":"v_a7f20fb5","type":"vote","entryId":"ad46dc5a","votedBelt":"Red","comment":"Onlypins,\\n\\nI feel like the tolerances and the security features of the 5/3 is still just as tough as the 6/4. ","userId":"pa0Fe38BgdV9fcL5PPNToNd7NVU2","displayName":"OnlyPins","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.802Z","updatedAt":"2026-10-09T23:23:56.802Z"},{"id":"v_bb11b638","type":"vote","entryId":"ad46dc5a","votedBelt":"Brown","comment":"all the ones I've seen are milled for 6/4 so shouldn't be red. especially the open side milling with all the min lifts\\nmasterlocksux","userId":"Kvf5QQTos8OCbgr8AkULzkWjVqr1","displayName":"MasterLockSux","source":"Classification Sheet","createdAt":"2026-10-09T23:24:56.802Z","updatedAt":"2026-10-09T23:24:56.802Z"},{"id":"v_070b0b6d","type":"vote","entryId":"cac56673","votedBelt":"Red","comment":"Probably sameline\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.473Z"},{"id":"v_3032166d","type":"vote","entryId":"2f556f68","votedBelt":"Brown","comment":"6 pin, 4 false gates.  Control is pretty easy after you get operating.  Probably sameline.  \\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.473Z"},{"id":"v_b1bb8a98","type":"vote","entryId":"2f556f68","votedBelt":"Brown","comment":"any shear should count for brown with the 6 pins ≥4 keypins with false gates, or both shears in one take for less false gate keypins \\nmasterlocksux","userId":"Kvf5QQTos8OCbgr8AkULzkWjVqr1","displayName":"MasterLockSux","source":"sheet","createdAt":"2026-10-12T23:38:02.473Z"},{"id":"v_760fcf7a","type":"vote","entryId":"ff45797b","votedBelt":"Black 2","comment":"5 rows, 17 pins.  Standard and spool drivers.  Great tolerances.  Very easy to overset.  Counter rotation needed to set spools and drops set pins.  Presetting possible but risks oversetting.  Pins are stainless steel.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.473Z"},{"id":"v_4375291a","type":"vote","entryId":"ff45797b","votedBelt":"Black 2","comment":"Jim\\nBB2. Nearly impossible not to overset something and need to drop pins and revisit them multiple times. Feedback is extremely subtle and you often have to depend on core shifts to tell when you have a row of pins completed. ","userId":"UbhgAjZIuLauV1dw2G4QsocHIk83","displayName":"Georgia Jim","source":"sheet","createdAt":"2026-10-12T23:38:02.473Z"},{"id":"v_a639d9a3","type":"vote","entryId":"4b13938b","votedBelt":"Blue","userId":"u_75b6a678","displayName":"Unknown","source":"sheet","createdAt":"2026-10-12T23:37:02.473Z"},{"id":"v_4c50432c","type":"vote","entryId":"a11d67f8","votedBelt":"Blue","comment":"Basically 0 warding, 5 standards, 4 sliders with no false gates. Teetering on the edge of green tbh.\\n\\n-Zehkar","userId":"1SqcRKce18boUZBtOHWSenGAI202","displayName":"Zehkar","source":"sheet","createdAt":"2026-10-12T23:37:02.473Z"},{"id":"v_de6cb8d2","type":"vote","entryId":"a11d67f8","votedBelt":"Blue","comment":"Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:38:02.473Z"},{"id":"v_57e5fa1b","type":"vote","entryId":"a11d67f8","votedBelt":"Blue","comment":"dimple/slider combo. 5 standard in main and 4 sliders. Wide open keyway.\\n\\n-Nightmare","userId":"kBjhBaserkb0dTYBtgzNcLddnyy1","displayName":"Nightmare","source":"sheet","createdAt":"2026-10-12T23:39:02.473Z"},{"id":"v_327ce149","type":"vote","entryId":"e6872b30","votedBelt":"Orange","comment":"Lock Noob","userId":"u_c940f29e","displayName":"Lock Noob","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.803Z","updatedAt":"2026-10-09T23:22:56.803Z"},{"id":"v_d3e8b93c","type":"vote","entryId":"d1f722e2","votedBelt":"Green","comment":"Very basic front tension dd with no false gates large true gates and terrible tolerances\\n\\nJim","userId":"UbhgAjZIuLauV1dw2G4QsocHIk83","displayName":"Georgia Jim","source":"sheet","createdAt":"2026-10-12T23:37:02.474Z"},{"id":"v_395aee6b","type":"vote","entryId":"d1f722e2","votedBelt":"Orange","comment":"crispix ","userId":"bSkotjOGENXHGd3rpo8G3TJeCk33","displayName":"Crispix","source":"sheet","createdAt":"2026-10-12T23:38:02.474Z"},{"id":"v_e5ba296a","type":"vote","entryId":"abdfe3dc","votedBelt":"Orange","comment":"Has some antipick elements with minor tapers and spools. Overall would be a good wafer for orange-green with only 5 wafers in it.\\n\\nCan fit up to 11 wafers which would be fun to rank but almost certainly not factory.\\n\\n~Bugasu","userId":"qtp7IM8d9sawUEAKsM0vwMITexR2","displayName":"Bugasu","source":"sheet","createdAt":"2026-10-12T23:37:02.474Z"},{"id":"v_e7737f86","type":"vote","entryId":"abdfe3dc","votedBelt":"Orange","comment":"A fun orange belt pick with some spooled wafers. So much core movement I thought I was open at some points lol. \\n\\n-Nightmare","userId":"kBjhBaserkb0dTYBtgzNcLddnyy1","displayName":"Nightmare","source":"sheet","createdAt":"2026-10-12T23:38:02.474Z"},{"id":"v_3e8f1855","type":"vote","entryId":"fb472463","votedBelt":"Green","comment":"NiXXeD\\nThis one had a favorable bitting. Pretty bad keyway could make any low/highs much more challenging than this, and I could easily see this being blue.","userId":"WMSvvuutyShfvBBYB3PmDe4fmeS2","displayName":"NiXXeD","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.803Z","updatedAt":"2026-10-09T23:22:56.803Z"},{"id":"v_18348712","type":"vote","entryId":"fb472463","votedBelt":"Blue","comment":"Nasty keyway for max lifts especially behind low lifts.  Put up more of a fight than I expected.  Thin lipped drivers were effective and gave some ping pong.\\n-Sidepicks ","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.803Z","updatedAt":"2026-10-09T23:23:56.803Z"},{"id":"v_7c6fff8d","type":"vote","entryId":"4150776b","votedBelt":"Black 1","userId":"u_10039c47","displayName":"Unknown","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.804Z","updatedAt":"2026-10-09T23:22:56.804Z"},{"id":"v_2b6725d0","type":"vote","entryId":"4150776b","votedBelt":"Black 1","comment":"the 6 rows make pretty cramped and annoying to navigate. it's easy to overset low rows while going for the middle ones. and as usual excellent tolerances.\\n-rein","userId":"f2yySWbxUBXF8k3HgorYhrm76gx2","displayName":"Reinder","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.804Z","updatedAt":"2026-10-09T23:23:56.804Z"},{"id":"v_79d80aa4","type":"vote","entryId":"8cf89508","votedBelt":"Green","comment":"4 levers only on one side.  Very shallow false gates that aren't effective.  Green is generous, could be orange.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.474Z"},{"id":"v_ae2ee5c0","type":"vote","entryId":"8cf89508","votedBelt":"Green","comment":"I think a yellow belt would find themselves totally lost in here, so my first thought is green. I could see orange as well though. - Marson","userId":"e2RNiz570rWqYYxDSDn6Y0uhgA43","displayName":"Marson","source":"sheet","createdAt":"2026-10-12T23:38:02.474Z"},{"id":"v_b3082e30","type":"vote","entryId":"feb61a7b","votedBelt":"Red","comment":"same as vm88 except tapered pins and smaller magnets, a lot more difficult than vm88. 6+6 elements.\\n-rein","userId":"f2yySWbxUBXF8k3HgorYhrm76gx2","displayName":"Reinder","source":"sheet","createdAt":"2026-10-12T23:37:02.474Z"},{"id":"v_c0c88cc4","type":"vote","entryId":"a666771a","votedBelt":"Purple","comment":"6 lever pump lock with a single spring that is very strong.  Easy to overset.  Would be much more difficult if levers had false gates.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.474Z"},{"id":"v_482d45ac","type":"vote","entryId":"8982fac6","votedBelt":"Green","comment":"6 pins, 3 spools 3 standards. Nothing special ","userId":"u_84ca1076","displayName":"Unknown","source":"sheet","createdAt":"2026-10-12T23:37:02.475Z"},{"id":"v_c7cf4ec5","type":"vote","entryId":"8982fac6","votedBelt":"Green","comment":"6 pin with spools and standards. Tough warding\\n\\n-Nightmare","userId":"kBjhBaserkb0dTYBtgzNcLddnyy1","displayName":"Nightmare","source":"sheet","createdAt":"2026-10-12T23:38:02.475Z"},{"id":"v_518159ca","type":"vote","entryId":"33b738f8","votedBelt":"Brown","comment":"6 levers behaving quite tapered, especially in the beginning. Anti pick is very effective and requires a deep counter rotation until the lever frees up, but then another lever drops and results in a ping pong battle between two levers. I have resorted to setting the front ping ponging lever first, and holding it with another wire in set position while counter rotating to set the other lever. \\nPlz7","userId":"qOSRbnEHbjcbQ7pT31Omv16R0NI3","displayName":"Plz7 ","source":"sheet","createdAt":"2026-10-12T23:37:02.475Z"},{"id":"v_3e8bdf2b","type":"vote","entryId":"e777ab2a","votedBelt":"Green","comment":"Did not gut but felt like 2 spools and 4 standard drivers\\n-Sidepicks\\n","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.475Z"},{"id":"v_c0779e9f","type":"vote","entryId":"e777ab2a","votedBelt":"Green","comment":"NiXXeD","userId":"WMSvvuutyShfvBBYB3PmDe4fmeS2","displayName":"NiXXeD","source":"sheet","createdAt":"2026-10-12T23:38:02.475Z"},{"id":"v_78f8d043","type":"vote","entryId":"3fd988f9","votedBelt":"Blue","comment":"11 pins.  Zero lifts are true zero lifts.  Need heavy pick pressure while slowly counter rotating as it gets closer to open.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.475Z"},{"id":"v_fbce5948","type":"vote","entryId":"ced4291e","votedBelt":"Purple","comment":"14 standards. 5 on left and right and 4 on top.\\n\\nNot really sure on the model name though. Bugasu says it could be k-lock according to their website.\\n\\n-Zehkar","userId":"1SqcRKce18boUZBtOHWSenGAI202","displayName":"Zehkar","source":"sheet","createdAt":"2026-10-12T23:37:02.475Z"},{"id":"v_02220324","type":"vote","entryId":"66dc5c9e","votedBelt":"Red","comment":"harder than 29 series by far. less elements than 30 series. good tolerances. false gates are a trap and need to be pre set. disconnected cam and plug. Retep","userId":"u_7e351cf1","displayName":"Retep","source":"sheet","createdAt":"2026-10-12T23:37:02.475Z"},{"id":"v_e27b2363","type":"vote","entryId":"ea4834c8","votedBelt":"Red","comment":"Red Wanderer - 14 pin 3 row dimple, lots of spool pins and some overset traps on the sides. Plug is lightly milled. Offset warding is kind of a pain. Seems fair to rank it in line with low pin count v18s, it's basically a clone although the plug isn't drilled for more pins than I had in mine.\\n\\nhttps://youtu.be/f2CQQd7Ch9Q","userId":"XoUDXU5McjTuVnPA1xfmzytcKuy2","displayName":"Red Wanderer","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.805Z","updatedAt":"2026-10-09T23:22:56.805Z"},{"id":"v_e507752a","type":"vote","entryId":"ea4834c8","votedBelt":"Red","comment":"Feels and looks very similar to the Showa NX, even has basically the same warding.  Loaner from Red but different lock than the one he ranked.  This one had 13 pin stacks, 1 dummy stack, and 1 centering bearing stack.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.805Z","updatedAt":"2026-10-09T23:23:56.805Z"},{"id":"v_b6f699ad","type":"vote","entryId":"0912d136","votedBelt":"Purple","comment":"lockpickingpaul\\n\\n8 sliders with false gates either side of the true gate, sliders are arranged in a row with 4 smaller sliders at the back and 4 larger sliders in front \\n\\nan additional opposing slider right at the back of the lock\\n\\nslider tips are triangulated making pick placement awkward, tension position restricts keyway\\n\\nsimilar picking experience to a Tubar once you dial into the false gates ","userId":"SyjMMYh9rYPI0lrxAWu5z5rrawx2","displayName":"Lock Picking Paul","source":"sheet","createdAt":"2026-10-12T23:37:02.476Z"},{"id":"v_0484e4c8","type":"vote","entryId":"2179a4a9","votedBelt":"Purple","comment":"Jim\\nDual row of slider sidebar design.  10 sliders (5 per row). Uses same slider design as Yale superior and other dimple slider designs.","userId":"UbhgAjZIuLauV1dw2G4QsocHIk83","displayName":"Georgia Jim","source":"sheet","createdAt":"2026-10-12T23:37:02.476Z"},{"id":"v_8d1ee4dd","type":"vote","entryId":"2179a4a9","votedBelt":"Purple","comment":"Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:38:02.476Z"},{"id":"v_953031db","type":"vote","entryId":"3bfcd36c","votedBelt":"Blue","userId":"u_d78b019d","displayName":"Unknown","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.805Z","updatedAt":"2026-10-09T23:22:56.805Z"},{"id":"v_fdadca7f","type":"vote","entryId":"3bfcd36c","votedBelt":"Blue","comment":"Lots of pins, but they all felt standard and some set just by scrubbing. \\n\\n-Nightmare\\n","userId":"kBjhBaserkb0dTYBtgzNcLddnyy1","displayName":"Nightmare","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.805Z","updatedAt":"2026-10-09T23:23:56.805Z"},{"id":"v_f3e1c805","type":"vote","entryId":"3bfcd36c","votedBelt":"Blue","comment":"12 standard pins 3 rows. feels low to middle blue \\nBrianBreaksShit ","userId":"tUMX51TojfWcZxzqpiPYKTnOnQg1","displayName":"BrianBreaksShit ","source":"Classification Sheet","createdAt":"2026-10-09T23:24:56.805Z","updatedAt":"2026-10-09T23:24:56.805Z"},{"id":"v_6369eff3","type":"vote","entryId":"3bfcd36c","votedBelt":"Blue","comment":"Blue feels pretty fair.  12 pins that all feel standard and set mostly with a light scrub. \\nKlettus","userId":"nOCg2aCpEgOI5lJOxwyScW9kXFX2","displayName":"Klettus","source":"Classification Sheet","createdAt":"2026-10-09T23:25:56.805Z","updatedAt":"2026-10-09T23:25:56.805Z"},{"id":"v_2b47e323","type":"vote","entryId":"c6cd3574","votedBelt":"Red","comment":"Weird and confusing.  6 Pins?/sliders? (3 on each side) that need lifted and rotated.  Very subtle feedback, almost nonexistent.  Everything is springy even when it's binding.  Even when it's picked and core is rotated all the pins are so springy that it needs a key retention mechanism (dimple in key and ball bearing in the core).  Key would be removable with core turned otherwise.  Would also agree with BB1.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.806Z","updatedAt":"2026-10-09T23:22:56.806Z"},{"id":"v_f4586b3c","type":"vote","entryId":"2ac99741","votedBelt":"Blue","comment":"clef\\neasy to tension\\na bit tapered, difficulty come from the fact than during the picking the internal rotate to a point where you can not reach the pins without super fin tools and move arround","userId":"tbaq0CWuDTXerA0eUi0kGASVb1Z2","displayName":"Clefmentine","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.806Z","updatedAt":"2026-10-09T23:22:56.806Z"},{"id":"v_a3883ba1","type":"vote","entryId":"2ac99741","votedBelt":"Blue","comment":"Peace: easy enough to pick the first few ones once you make a simple tensioner that works. but last few picks are way behind the fixed face plate, not easy to reach for.","userId":"mZyfQIARjCP1uJJJc7ioMAALV9v2","displayName":"PeaceWeapon","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.806Z","updatedAt":"2026-10-09T23:23:56.806Z"},{"id":"v_06b3ed06","type":"vote","entryId":"3a58178a","votedBelt":"Black 2","comment":"clef\\nverry hard in pin in pin cause of the deep falsets and the one really strong spring\\ngrab the slider insead of just pushing it for better feed backs","userId":"tbaq0CWuDTXerA0eUi0kGASVb1Z2","displayName":"Clefmentine","source":"sheet","createdAt":"2026-10-12T23:37:02.477Z"},{"id":"v_0dd31917","type":"vote","entryId":"3a58178a","votedBelt":"Black 2","userId":"u_ded293f2","displayName":"Unknown","source":"sheet","createdAt":"2026-10-12T23:38:02.477Z"},{"id":"v_a6a63a93","type":"vote","entryId":"e2c9b69e","votedBelt":"Brown","comment":"6 pins in the main stack, 8 active side pins (4 on each side).\\nKeyway is a bit tricky, side pins might  prevent navigating the keyway easily.\\n\\n-baikunz","userId":"YYh4QtNUrba1xOqNm9z2GqG7ssO2","displayName":"baikunz","source":"sheet","createdAt":"2026-10-12T23:37:02.477Z"},{"id":"v_0adf9266","type":"vote","entryId":"3ca24202","votedBelt":"Purple","comment":"Craig: this felt purple to me. Some pins have to be mapped out because they bind no matter what, due to the second shearline, but the rest are easy. Could be a lot of variation with these.","userId":"u_9a4c8f0f","displayName":"Craig","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.806Z","updatedAt":"2026-10-09T23:22:56.806Z"},{"id":"v_dfa38bf5","type":"vote","entryId":"3ca24202","votedBelt":"Purple","comment":"clef\\nsame as pollux 5 but most of them are mastered so two sheer lines can be really tricky if the lock is dusty","userId":"tbaq0CWuDTXerA0eUi0kGASVb1Z2","displayName":"Clefmentine","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.806Z","updatedAt":"2026-10-09T23:23:56.806Z"},{"id":"v_4a0e7487","type":"vote","entryId":"3ca24202","votedBelt":"Purple","comment":"felt purple, keyway is easily open and the feedback is generally ok except for one or two pin that are mushy. not too hard but the mushy pins can really gunk up your feeling until you almost stumble into the open\\n-Alpama","userId":"FGhShmNkxTXC9vwmZwWylOvU8K72","displayName":"Alpama","source":"Classification Sheet","createdAt":"2026-10-09T23:24:56.806Z","updatedAt":"2026-10-09T23:24:56.806Z"},{"id":"v_e9f2a513","type":"vote","entryId":"f5086cb9","votedBelt":"Purple","comment":"Like Pollux 7 but with master ring. Pretty straightforward. Tap tap tap. Gutting is tricky. - Greenish","userId":"NdkmYGydSHfPTcj5xuqjwSyJJI42","displayName":"Greenish","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.807Z","updatedAt":"2026-10-09T23:22:56.807Z"},{"id":"v_f4cb098c","type":"vote","entryId":"f5086cb9","votedBelt":"Purple","comment":"clef\\n","userId":"tbaq0CWuDTXerA0eUi0kGASVb1Z2","displayName":"Clefmentine","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.807Z","updatedAt":"2026-10-09T23:23:56.807Z"},{"id":"v_00caad6e","type":"vote","entryId":"f5086cb9","votedBelt":"Brown","comment":"Tapers tapers tapers. Mastering makes the gutting a bit tricky.\\n-baikunz","userId":"YYh4QtNUrba1xOqNm9z2GqG7ssO2","displayName":"baikunz","source":"Classification Sheet","createdAt":"2026-10-09T23:24:56.807Z","updatedAt":"2026-10-09T23:24:56.807Z"},{"id":"v_91d3e270","type":"vote","entryId":"f5086cb9","votedBelt":"Brown","comment":"Picks the same as the Pollux 7, pretty much, maybe a bit more tapered action in this. Not much different\\n-Zehkar","userId":"1SqcRKce18boUZBtOHWSenGAI202","displayName":"Zehkar","source":"Classification Sheet","createdAt":"2026-10-09T23:25:56.807Z","updatedAt":"2026-10-09T23:25:56.807Z"},{"id":"v_a143129d","type":"vote","entryId":"f5086cb9","votedBelt":"Brown","comment":"Mine was a bit harder than my Pollux 7.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T23:26:56.807Z","updatedAt":"2026-10-09T23:26:56.807Z"},{"id":"v_12c2c04d","type":"vote","entryId":"4164c937","votedBelt":"Purple","comment":"6 pin pump lock with a trap pin that engages twice when rotating 360 degrees as well as 2 of the normal 6 pins that re-engage at 180 degrees.\\n\\nVery very similar experience to the ISEO Perfecta, the only difference being that it’s a lot easier to deal with the trap pin on this one vs the perfecta. Might lean a bit more into blue solely because of that but I’ll leave it purple for now.\\n\\n-Zehkar ","userId":"1SqcRKce18boUZBtOHWSenGAI202","displayName":"Zehkar","source":"sheet","createdAt":"2026-10-12T23:37:02.477Z"},{"id":"v_84500321","type":"vote","entryId":"9637ddde","votedBelt":"Brown","comment":"This is a complex dimple lock with effective sliders. Could be red, could be brown. I've only seen 1 -\\n GravityKarma\\n","userId":"8PKfUHTiafgObsQQr162dQRlBCo1","displayName":"GravityKarma","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.807Z","updatedAt":"2026-10-09T23:22:56.807Z"},{"id":"v_e1576b71","type":"vote","entryId":"aaca6c85","votedBelt":"Blue","comment":"Could be samelined with MTL/Kenaurd.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.807Z","updatedAt":"2026-10-09T23:22:56.807Z"},{"id":"v_e7661a4f","type":"vote","entryId":"aaca6c85","votedBelt":"Blue","comment":"NiXXeD\\nFelt like Kenaurd. Chase the binder.","userId":"WMSvvuutyShfvBBYB3PmDe4fmeS2","displayName":"NiXXeD","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.807Z","updatedAt":"2026-10-09T23:23:56.807Z"},{"id":"v_8b4a31fe","type":"vote","entryId":"aaca6c85","votedBelt":"Blue","comment":"Same lock as sidepicks. Feels worse than MTL to me.\\n-BurnB1","userId":"ogrEbc6fjmVOKtvfZ7vENh6oX072","displayName":"Burnetb1","source":"Classification Sheet","createdAt":"2026-10-09T23:24:56.807Z","updatedAt":"2026-10-09T23:24:56.807Z"},{"id":"v_4f177faa","type":"vote","entryId":"6cb514ea","votedBelt":"Blue","comment":"Jim\\nLower tolerance MTL Interactive clone.  Mix of standard and spools (3 spool, 2 standard) blue at 5 pins, green at 4 pins. ","userId":"UbhgAjZIuLauV1dw2G4QsocHIk83","displayName":"Georgia Jim","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.808Z","updatedAt":"2026-10-09T23:22:56.808Z"},{"id":"v_672a4806","type":"vote","entryId":"6cb514ea","votedBelt":"Purple","comment":"mgsecure. poor tolerances, might rank blue but we have the \\"Any MTL Interactive Clone\\" entry at Purple. Pics at https://lpubelts.com/#/locks?search=ri-&tab=search&id=6cb514ea&name=RiKey_High_Security_MTL_clone\\n","userId":"GGplAdctTfVDLVvYsfIADJmfp8f2","displayName":"mgsecure","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.808Z","updatedAt":"2026-10-09T23:23:56.808Z"},{"id":"v_81fe1e5e","type":"vote","entryId":"6cb514ea","votedBelt":"Green","comment":" Agree with J.im. 4 pin should be Green. I'd hate to have more splits on these PIPs, but manufacturing quality does vary. -VectorPotential\\n","userId":"6dSEXTn8flPPg4EV5IlSQWGVT983","displayName":"VectorPotential","source":"Classification Sheet","createdAt":"2026-10-09T23:24:56.808Z","updatedAt":"2026-10-09T23:24:56.808Z"},{"id":"v_abfb2ab8","type":"vote","entryId":"6cb514ea","votedBelt":"Blue","comment":"Spy-c, I agree with J.im and Vector 4 pin green/5 pin blue it sits somewhere between Kenuard and Deguard in my head","userId":"VBmk1eBTsyeE3MqvDJMRrWoM3mt1","displayName":"Spyc","source":"Classification Sheet","createdAt":"2026-10-09T23:25:56.808Z","updatedAt":"2026-10-09T23:25:56.808Z"},{"id":"v_203a3cb7","type":"vote","entryId":"6cb514ea","votedBelt":"Blue","comment":"I dont even know why we have \\"Any HQ Interactive Clone\\" if we're going to rank each one. Imo remove that entry and RiKey 4pin at Green and RiKey 5 pin at Blue.\\n\\nI don't think it deserves Purple like MTL because at least my examples are quite loose and unlike MTL it requires some very sloppy picking to drop any set spools.\\n~Bugasu","userId":"qtp7IM8d9sawUEAKsM0vwMITexR2","displayName":"Bugasu","source":"Classification Sheet","createdAt":"2026-10-09T23:26:56.808Z","updatedAt":"2026-10-09T23:26:56.808Z"},{"id":"v_71590a8a","type":"vote","entryId":"6cb514ea","votedBelt":"Blue","userId":"u_f51b4824","displayName":"Unknown","source":"Classification Sheet","createdAt":"2026-10-09T23:27:56.808Z","updatedAt":"2026-10-09T23:27:56.808Z"},{"id":"v_d6e01717","type":"vote","entryId":"d87bb501","votedBelt":"Yellow","comment":"5 pin all standards but is one of the trickier 5 pin standard locks I've picked.  Easy to overset.  I would agree with orange as well.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.808Z","updatedAt":"2026-10-09T23:22:56.808Z"},{"id":"v_7c2e8cc8","type":"vote","entryId":"d87bb501","votedBelt":"Orange","comment":"Spy-c, some higher lifts in mine that made me wish I had one at orange to teach me about warding as a ledge and bok inserts for height","userId":"VBmk1eBTsyeE3MqvDJMRrWoM3mt1","displayName":"Spyc","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.808Z","updatedAt":"2026-10-09T23:23:56.808Z"},{"id":"v_e3486620","type":"vote","entryId":"7797cdaa","votedBelt":"Yellow","comment":"mgsecure","userId":"GGplAdctTfVDLVvYsfIADJmfp8f2","displayName":"mgsecure","source":"sheet","createdAt":"2026-10-12T23:37:02.479Z"},{"id":"v_7163666d","type":"vote","entryId":"7797cdaa","votedBelt":"Yellow","comment":"One of the first locks I picked. Pretty straightforward, pretty sure its all standards in my two examples (I have both the 40mm and 50mm)\\n~ Bugasu","userId":"qtp7IM8d9sawUEAKsM0vwMITexR2","displayName":"Bugasu","source":"sheet","createdAt":"2026-10-12T23:38:02.479Z"},{"id":"v_ef0a4a43","type":"vote","entryId":"7df18b83","votedBelt":"Yellow","comment":"mgsecure","userId":"GGplAdctTfVDLVvYsfIADJmfp8f2","displayName":"mgsecure","source":"sheet","createdAt":"2026-10-12T23:37:02.479Z"},{"id":"v_a82aed4f","type":"vote","entryId":"7df18b83","votedBelt":"Yellow","comment":"Very similar if not the same as the laminated padlock, but I have not gut the internals to compare. 5 pins, the feedback in my brass padlock was worse than in the laminated.\\n~ Bugasu\\n","userId":"qtp7IM8d9sawUEAKsM0vwMITexR2","displayName":"Bugasu","source":"sheet","createdAt":"2026-10-12T23:38:02.479Z"},{"id":"v_83942343","type":"vote","entryId":"9b528165","votedBelt":"Purple","comment":"purple/brown, it's like a smaller 32a and has only 6 disks\\n\\n-rein","userId":"f2yySWbxUBXF8k3HgorYhrm76gx2","displayName":"Reinder","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.809Z","updatedAt":"2026-10-09T23:22:56.809Z"},{"id":"v_ed3ae2d4","type":"vote","entryId":"5646568c","votedBelt":"Black 5","comment":"tonysansan\\n\\nThere are deep false gates everywhere. Requires delicate motions to determine disc state and to advance step by step without oversetting. Easy to touch a disc and knock it out of position. One error and the picking attempt is over.","userId":"BJyWOIOsqmRDkgHZBqIEGbGnVSA3","displayName":"tonysansan","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.809Z","updatedAt":"2026-10-09T23:22:56.809Z"},{"id":"v_0608e16a","type":"vote","entryId":"d78c58be","votedBelt":"Purple","comment":"I picked it both w/ 2-in-1 and w/ wire. Tapered & false gates. Needs gobs of tension. Already has an unranked entry w/ photos.\\n-Marson","userId":"e2RNiz570rWqYYxDSDn6Y0uhgA43","displayName":"Marson","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.809Z","updatedAt":"2026-10-09T23:22:56.809Z"},{"id":"v_5595e761","type":"vote","entryId":"d78c58be","votedBelt":"Purple","comment":"Agree with M.arson. Effective false gates, needed to pre-lift some levers. Lots of tension. Picked with wire - Greenish","userId":"NdkmYGydSHfPTcj5xuqjwSyJJI42","displayName":"Greenish","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.809Z","updatedAt":"2026-10-09T23:23:56.809Z"},{"id":"v_155a39b2","type":"vote","entryId":"9b74968b","votedBelt":"Blue","comment":"spacenut1: I picked the Royal Guardian-EX, which seems significantly easier as it only has two trap pins (in the top stack, not the side), and the trap can be recovered without gutting. The side pin in mine was also passive and could be ignored. If splitting the listing for EX and non-EX is too annoying, it could be like Kwikset Smartkey, some people just get an easy purple.","userId":"u_63fc3f33","displayName":"spacenut1","source":"sheet","createdAt":"2026-10-12T23:37:02.479Z"},{"id":"v_140c1b60","type":"vote","entryId":"9b74968b","votedBelt":"Blue","comment":"5 pin with 2 trap pins.  One passive side pin.  Setting drivers is trivial and only real challenge is dealing with the 2 trap pins.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:38:02.479Z"},{"id":"v_ffbbbbf2","type":"vote","entryId":"d2427e16","votedBelt":"Orange","userId":"u_6ee103a5","displayName":"Unknown","source":"sheet","createdAt":"2026-10-12T23:37:02.479Z"},{"id":"v_356ab499","type":"vote","entryId":"e713e7e6","votedBelt":"Green","comment":"Peace: pretty fun. Challenging enough","userId":"mZyfQIARjCP1uJJJc7ioMAALV9v2","displayName":"PeaceWeapon","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.809Z","updatedAt":"2026-10-09T23:22:56.809Z"},{"id":"v_e76f8362","type":"vote","entryId":"e713e7e6","votedBelt":"Blue","comment":"Yagias:\\nGood fun and much trickier than say an ACE II, Requires custom tensioning tool.","userId":"u_89015b15","displayName":"Yagias","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.809Z","updatedAt":"2026-10-09T23:23:56.809Z"},{"id":"v_a14f501e","type":"vote","entryId":"e713e7e6","votedBelt":"Blue","comment":"spring from the lock make it hard to tension and after it's 5 tappered pins it goes pok pok pok and open\\nclef","userId":"tbaq0CWuDTXerA0eUi0kGASVb1Z2","displayName":"Clefmentine","source":"Classification Sheet","createdAt":"2026-10-09T23:24:56.809Z","updatedAt":"2026-10-09T23:24:56.809Z"},{"id":"v_59960218","type":"vote","entryId":"8a4642d6","votedBelt":"Orange","comment":"Tapered and subtle feedback\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.480Z"},{"id":"v_5ee5dbe2","type":"vote","entryId":"8a4642d6","votedBelt":"Orange","comment":"5 standard drivers, open keyway. Picked with MP13. Felt slightly tapered, but I think the lock was just dirty. \\n\\n-Nightmare","userId":"kBjhBaserkb0dTYBtgzNcLddnyy1","displayName":"Nightmare","source":"sheet","createdAt":"2026-10-12T23:38:02.480Z"},{"id":"v_10e588c4","type":"vote","entryId":"39aedf60","votedBelt":"Purple","comment":"Pretty much a Medeco M3 without rotating 6th pin.  This was LFIC version picked to both shear lines.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.480Z"},{"id":"v_66137fa0","type":"vote","entryId":"39aedf60","votedBelt":"Purple","comment":"This seems to be a Sargent branded Medeco M3 LFIC. Pin 6 is not a gated pin and doesn't interact with the sidebar. The one I picked had a couple of mushroom drivers and an ASSA barrel, but no countermilling that I recall. I'd say it's on the high end of purple. Peskier than I would expect based on what's in there, but otherwise nothing extraordinary. -Hog","userId":"hnX373zhNoT1QZ3lc8IWVEvcz0R2","displayName":"DoctorHogmaster","source":"sheet","createdAt":"2026-10-12T23:38:02.480Z"},{"id":"v_1ed2ec1a","type":"vote","entryId":"1ee6cef3","votedBelt":"Purple","comment":"Picking to both shear lines is somewhat trivial because it's like Medeco where 3 and 4 just need to be lifted a bit higher.  \\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.480Z"},{"id":"v_bb4fc776","type":"vote","entryId":"b6179140","votedBelt":"Green","comment":"Sargent version of the Everest but with better tolerances.  Everest I feel should be orange but with the tolerances of this one I think it could maybe be green.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.480Z"},{"id":"v_4f8085b0","type":"vote","entryId":"8a7eee5c","votedBelt":"Red","comment":"I believe it's around red belt level- the levers are very close together a d it's easy to slip off or move 2 levers instead of one, also requires floatpicking - my video here: https://youtu.be/KzGpTGLaY6Y?si=RE_e1Jgaa80xcegf\\n-DQ","userId":"qXhqtUdEVFfrajxqblKl8bqQqXM2","displayName":"DQ","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.810Z","updatedAt":"2026-10-09T23:22:56.810Z"},{"id":"v_29ff8018","type":"vote","entryId":"a72739bc","votedBelt":"Black 2","comment":"This lock is a struggle. Very easy to unset pins, requires all custom non-magnetic tooling, the very limited space is a challenge of its own, and some of the chambers have a kind of reverse T effect that drops you into a nasty \\"false set\\".\\n- DND","userId":"XKPQaAR525XV2JsqGn12eEKwxD62","displayName":"DoNotDuplicate","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.810Z","updatedAt":"2026-10-09T23:22:56.810Z"},{"id":"v_d2309efd","type":"vote","entryId":"6f61cebf","votedBelt":"Orange","comment":"5 standards and 1 spool with somewhat of an annoying warding for high lifts. High orange low green \\n\\n-Zehkar","userId":"1SqcRKce18boUZBtOHWSenGAI202","displayName":"Zehkar","source":"sheet","createdAt":"2026-10-12T23:37:02.480Z"},{"id":"v_b18b3b0f","type":"vote","entryId":"6f61cebf","votedBelt":"Green","comment":"Decent tolerances for a Securemme.  Slightly tapered feel.  Warding makes high lifts a bit challenging.  Solid green.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:38:02.480Z"},{"id":"v_68bdade2","type":"vote","entryId":"6f61cebf","votedBelt":"Green","comment":"6 pins, 5 standard and 1 spool. Felt slightly tapered and effective warding. \\n\\n-Nightmare","userId":"kBjhBaserkb0dTYBtgzNcLddnyy1","displayName":"Nightmare","source":"sheet","createdAt":"2026-10-12T23:39:02.480Z"},{"id":"v_f6afff1f","type":"vote","entryId":"20b7f0a3","votedBelt":"Purple","comment":"5 pins plus interactive and 4 sprung sliders all with false gates (3 of them had active false gates).\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.481Z"},{"id":"v_55534b1b","type":"vote","entryId":"20b7f0a3","votedBelt":"Purple","comment":"5 pin dimple + spool interactive with 4 false gated sprung sliders. \\n\\n-Nightmare\\n\\n","userId":"kBjhBaserkb0dTYBtgzNcLddnyy1","displayName":"Nightmare","source":"sheet","createdAt":"2026-10-12T23:38:02.481Z"},{"id":"v_03d6a66b","type":"vote","entryId":"20b7f0a3","votedBelt":"Purple","comment":"5 standards, 1 interactive element spool, sidebar for 4 sprung sliders with false gates.\\n\\n-Zehkar","userId":"1SqcRKce18boUZBtOHWSenGAI202","displayName":"Zehkar","source":"sheet","createdAt":"2026-10-12T23:39:02.481Z"},{"id":"v_13c15549","type":"vote","entryId":"55d4676c","votedBelt":"Blue","comment":"8 pins with 3 sprung sliders.  Very similar to Yale 2000 plus, DAF Kilit, and Mottura Viper.  I don't know if the 2 less pins and one less slider is enough for a belt drop but it could be.  All these locks are fairly similar and fairly easy but very fun.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.811Z","updatedAt":"2026-10-09T23:22:56.811Z"},{"id":"v_d5bca35d","type":"vote","entryId":"55d4676c","votedBelt":"Purple","comment":"NiXXeD\\nNot quite easy enough for blue imo. Felt really similar to the Yale like this.","userId":"WMSvvuutyShfvBBYB3PmDe4fmeS2","displayName":"NiXXeD","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.811Z","updatedAt":"2026-10-09T23:23:56.811Z"},{"id":"v_f3ee7a00","type":"vote","entryId":"55d4676c","votedBelt":"Purple","comment":"Same lock as Side.picks\\n-BurnB1","userId":"ogrEbc6fjmVOKtvfZ7vENh6oX072","displayName":"Burnetb1","source":"Classification Sheet","createdAt":"2026-10-09T23:24:56.811Z","updatedAt":"2026-10-09T23:24:56.811Z"},{"id":"v_2bfb0029","type":"vote","entryId":"55d4676c","votedBelt":"Purple","comment":"Red Wanderer - Same lock as Nix.xed. Definitely in the high blue - purple range. Sliders didn't feel consequential, but the high lift pins are rough and the spools tend to drop things.","userId":"XoUDXU5McjTuVnPA1xfmzytcKuy2","displayName":"Red Wanderer","source":"Classification Sheet","createdAt":"2026-10-09T23:25:56.811Z","updatedAt":"2026-10-09T23:25:56.811Z"},{"id":"v_1a3c0c85","type":"vote","entryId":"0874768d","votedBelt":"Orange","comment":"5 pin standard drivers\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.481Z"},{"id":"v_9375fb3c","type":"vote","entryId":"7b7bddf9","votedBelt":"Red","comment":"20 pins in 4 rows.  Needle key pins and standard drivers, no milling.  Needle pins are slightly annoying to deal with.  Somewhat subtle feedback.  Mostly isolated.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.481Z"},{"id":"v_1c6b1716","type":"vote","entryId":"6bcf62ed","votedBelt":"Green","comment":"6 spools, 2 passives, okay tolerances on my 2 examples. Fairly straightforward.\\n\\nI'd say its harder than all of the locks I've picked at orange, but I could see hard orange/easy green.\\n~ Bugasu\\n","userId":"qtp7IM8d9sawUEAKsM0vwMITexR2","displayName":"Bugasu","source":"sheet","createdAt":"2026-10-12T23:37:02.481Z"},{"id":"v_d99eefe7","type":"vote","entryId":"6c395573","votedBelt":"Black 2","comment":"Appears to be a near exact reproduction of the Segal Pickproof.  5 pins with different diameter key pins, spooled gin drivers that get stuck in the floating slotted sleeve if not set to the proper height.  If core is turned before all spooled gins are above the sleeve it basically forces a reset.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.812Z","updatedAt":"2026-10-09T23:22:56.812Z"},{"id":"v_96b28658","type":"vote","entryId":"6c395573","votedBelt":"Black 2","comment":"tonysansan\\n\\nSleeve makes main pins much harder than those of 6k with gins, though there is one fewer pin and no sidebar.","userId":"BJyWOIOsqmRDkgHZBqIEGbGnVSA3","displayName":"tonysansan","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.812Z","updatedAt":"2026-10-09T23:23:56.812Z"},{"id":"v_68cf9274","type":"vote","entryId":"452aaa17","votedBelt":"Orange","comment":"Mugatu\\n3 levers on each side of pipe pin, one sheet of metal warding seperating levers 1 from 2&3. Levers interact directly with the shackle.","userId":"u_f278d262","displayName":"Mugatu","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.812Z","updatedAt":"2026-10-09T23:22:56.812Z"},{"id":"v_b64dcc97","type":"vote","entryId":"4d5025e5","votedBelt":"Purple","comment":"Tubular lock combined with a pin tumbler.  6 \\"tubular\\" style pins, 5 bottom pins.  I would agree with brown.  There are several brown pump locks that should be purple imo and feel very similar to this one.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.482Z"},{"id":"v_ec2dccbd","type":"vote","entryId":"97baf67b","votedBelt":"White","comment":"\\nPanda-Frog","userId":"u_93bfb607","displayName":"Panda Frog","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.812Z","updatedAt":"2026-10-09T23:22:56.812Z"},{"id":"v_afe3d92f","type":"vote","entryId":"0d0bf1a5","votedBelt":"White","comment":"\\nPanda-Frog","userId":"u_93bfb607","displayName":"Panda Frog","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.812Z","updatedAt":"2026-10-09T23:22:56.812Z"},{"id":"v_1f3d7baa","type":"vote","entryId":"29d423c8","votedBelt":"Yellow","comment":"Panda-Frog","userId":"u_93bfb607","displayName":"Panda Frog","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.812Z","updatedAt":"2026-10-09T23:22:56.812Z"},{"id":"v_a6c11bfa","type":"vote","entryId":"53365ed3","votedBelt":"Orange","comment":"Panda-Frog","userId":"u_93bfb607","displayName":"Panda Frog","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.812Z","updatedAt":"2026-10-09T23:22:56.812Z"},{"id":"v_b96abde3","type":"vote","entryId":"ae8de4ca","votedBelt":"Yellow","comment":"White or yellow. Easier than 440 as it didn't as much tension. — Marson","userId":"e2RNiz570rWqYYxDSDn6Y0uhgA43","displayName":"Marson","source":"sheet","createdAt":"2026-10-12T23:37:02.482Z"},{"id":"v_ec2363e0","type":"vote","entryId":"e390a509","votedBelt":"Yellow","comment":"Much like the 220. Easier than the others. I picked it with a windshield wiper and a hook. — Marson","userId":"e2RNiz570rWqYYxDSDn6Y0uhgA43","displayName":"Marson","source":"sheet","createdAt":"2026-10-12T23:37:02.482Z"},{"id":"v_3d0be5f0","type":"vote","entryId":"6d63be2d","votedBelt":"Yellow","comment":"Both the brass and stainless levers are more slippery than the forged steel ones in the 440, but I don't know if it bumps it up another rank. I'd be fine with either yellow or orange.\\n — Marson","userId":"e2RNiz570rWqYYxDSDn6Y0uhgA43","displayName":"Marson","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.812Z","updatedAt":"2026-10-09T23:22:56.812Z"},{"id":"v_d4e73649","type":"vote","entryId":"924ed819","votedBelt":"Yellow","comment":"Both the brass and stainless levers are more slippery than the forged steel ones in the 440, but I don't know if it bumps it up another rank. I'd be fine with either yellow or orange.\\n — Marson","userId":"e2RNiz570rWqYYxDSDn6Y0uhgA43","displayName":"Marson","source":"sheet","createdAt":"2026-10-12T23:37:02.483Z"},{"id":"v_5133a59b","type":"vote","entryId":"4709ce45","votedBelt":"Green","comment":"Even though it's just 4 levers with no anti-pick, the gorilla tension needed made this a couple steps up from the other squires even using a 2-in-1.\\n— Marson","userId":"e2RNiz570rWqYYxDSDn6Y0uhgA43","displayName":"Marson","source":"sheet","createdAt":"2026-10-12T23:37:02.483Z"},{"id":"v_6a490c95","type":"vote","entryId":"df974350","votedBelt":"Blue","comment":"6 pins, tapered drivers.  Very tapered.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.483Z"},{"id":"v_4d2f9db8","type":"vote","entryId":"df974350","votedBelt":"Blue","comment":"6 taper pins. most key pins are torpedos.  all pins needing multiple taps. \\n         BrianBreaksShit ","userId":"tUMX51TojfWcZxzqpiPYKTnOnQg1","displayName":"BrianBreaksShit ","source":"sheet","createdAt":"2026-10-12T23:38:02.483Z"},{"id":"v_a55159db","type":"vote","entryId":"723977f4","votedBelt":"Purple","comment":"8 sliders with 2 false gates each.  False gates are effective.  As you get more set or in false gates floating becomes necessary and moving past false gates will cause others to drop.  Presetting is possible but not necessary.\\n-Sidepicks\\n\\nhttps://imgur.com/a/suame-slider-lock-CQHXEPr","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.483Z"},{"id":"v_382f535e","type":"vote","entryId":"723977f4","votedBelt":"Brown","comment":"Jim\\n8 sliders with very effective false gates that require a lot of counter rotation to get out of the mul-t-lock levels of deep false sets. Calling it brown because I find it harder than desmo and much harder than something like a serrated mul-t-lock.","userId":"UbhgAjZIuLauV1dw2G4QsocHIk83","displayName":"Georgia Jim","source":"sheet","createdAt":"2026-10-12T23:38:02.483Z"},{"id":"v_0e25764e","type":"vote","entryId":"53e74a74","votedBelt":"Purple","comment":"lockpickingpaul\\n\\n13 tapered pins in 3 offset rows, needs to be tensioned from the bottom of the lock using a custom tensioner, radial/axial format cylinder\\n\\nPins are heavily tapered, very little room in the keyway but it's difficult to overset \\n\\nthe real challenge is in making the tensioner and patience, don't gut this lock (ask me how I know) \\n\\nharder than a Vanlock or TuBAR, possibly Brown belt ","userId":"SyjMMYh9rYPI0lrxAWu5z5rrawx2","displayName":"Lock Picking Paul","source":"sheet","createdAt":"2026-10-12T23:37:02.483Z"},{"id":"v_f5b384e0","type":"vote","entryId":"53e74a74","votedBelt":"Purple","comment":"Mine had 10 pins in 5 rows (12, 2, 4, 8, and 10 o'clock positions).  Tensioning was biggest challenge but not that bad.  Used the tiny MP Z shaped tensioner.  In terms of difficulty it felt blue but working out tensioning maybe bumps it to purple.\\n-Sidepicks\\n\\nhttps://imgur.com/a/sb-super-bright-efGLBUC","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:38:02.483Z"},{"id":"v_0ad432d8","type":"vote","entryId":"a77899fe","votedBelt":"Blue","comment":"Jim","userId":"UbhgAjZIuLauV1dw2G4QsocHIk83","displayName":"Georgia Jim","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.813Z","updatedAt":"2026-10-09T23:22:56.813Z"},{"id":"v_28dda411","type":"vote","entryId":"174e20c0","votedBelt":"Brown","comment":"Small with unusual feedback and navigation, but ok manipulation once understood.\\ncrispix ","userId":"bSkotjOGENXHGd3rpo8G3TJeCk33","displayName":"Crispix","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.813Z","updatedAt":"2026-10-09T23:22:56.813Z"},{"id":"v_f20a8a54","type":"vote","entryId":"2ad511f9","votedBelt":"Blue","comment":"LockFumbler:\\nnasty small check pin, but for me this needed to be set first and then main stack. Main stack had typical tapered drivers -> tapping, tapping, tapping\\npinning: 1+2 \\"Barrels\\"\\n3-6 \\"Spools\\"\\n(no false set due to bad bitting...)\\n","userId":"gWoqbd0FOsglFD5boH96NAtJ7DE3","displayName":"LockFumbler","source":"sheet","createdAt":"2026-10-12T23:37:02.484Z"},{"id":"v_3306b95d","type":"vote","entryId":"156e33aa","votedBelt":"Black 1","comment":"21 pins in 5 rows.  Easy to overset.  My opens have come from dropping oversets.  Would be better with overmilling.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.484Z"},{"id":"v_272f6d6e","type":"vote","entryId":"156e33aa","votedBelt":"Black 1","comment":"Jim\\nI’m borderline if this deserves bb2 or not. With the pin count and layout it’s harder than a 5 Row Kaba Star and the feedback is really hard to decipher until you have the majority of the pins set. ","userId":"UbhgAjZIuLauV1dw2G4QsocHIk83","displayName":"Georgia Jim","source":"sheet","createdAt":"2026-10-12T23:38:02.484Z"},{"id":"v_262c26ac","type":"vote","entryId":"7859ad67","votedBelt":"Green","comment":"Jim\\nVery similar to Kryptonite round body padlock. No harder than Green.","userId":"UbhgAjZIuLauV1dw2G4QsocHIk83","displayName":"Georgia Jim","source":"sheet","createdAt":"2026-10-12T23:37:02.484Z"},{"id":"v_33154f9d","type":"vote","entryId":"49d28606","votedBelt":"Green","comment":"Jim\\nSame core as TBK90R just in aluminum 1100 style body","userId":"UbhgAjZIuLauV1dw2G4QsocHIk83","displayName":"Georgia Jim","source":"sheet","createdAt":"2026-10-12T23:37:02.484Z"},{"id":"v_92270b30","type":"vote","entryId":"5ecc7279","votedBelt":"Green","comment":"Jim\\n50mm brass padlock, 6 pins 5 spools, feels as hard as something like an Ace hardware brass padlock.","userId":"UbhgAjZIuLauV1dw2G4QsocHIk83","displayName":"Georgia Jim","source":"sheet","createdAt":"2026-10-12T23:37:02.484Z"},{"id":"v_a24dc138","type":"vote","entryId":"614f838f","votedBelt":"Orange","comment":"Jim\\n40mm brass padlock, picks similar to master 150, orange feels very fair and too hard for yellow.","userId":"UbhgAjZIuLauV1dw2G4QsocHIk83","displayName":"Georgia Jim","source":"sheet","createdAt":"2026-10-12T23:37:02.485Z"},{"id":"v_bb8b5cad","type":"vote","entryId":"7e186e02","votedBelt":"Green","comment":"Jim\\n7 discs can be rear tensioned or front if front disc is counter rotated. If Zarker J45 is green then this is similar difficulty, harder than the cheaper Chinese DD locks. ","userId":"UbhgAjZIuLauV1dw2G4QsocHIk83","displayName":"Georgia Jim","source":"sheet","createdAt":"2026-10-12T23:37:02.485Z"},{"id":"v_56a8d884","type":"vote","entryId":"a3b983b7","votedBelt":"Blue","comment":"peace: reverse sidebar, but some poking and jiggling and it sets itself eventually","userId":"mZyfQIARjCP1uJJJc7ioMAALV9v2","displayName":"PeaceWeapon","source":"sheet","createdAt":"2026-10-12T23:37:02.485Z"},{"id":"v_30035706","type":"vote","entryId":"a3b983b7","votedBelt":"Blue","comment":"There was clear feedback.  Can basically be fumbled open with a couple picks and some wiggling but could be challenging depending on bitting maybe.  Also would be more effective with stronger springs.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:38:02.485Z"},{"id":"v_34b014df","type":"vote","entryId":"9a99a0a7","votedBelt":"White","comment":"Old model but sometimes available secondhand. 4 standard pins, nothing fancy.\\nMoki","userId":"u_c3c19741","displayName":"Moki","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.814Z","updatedAt":"2026-10-09T23:22:56.814Z"},{"id":"v_6aa4200a","type":"vote","entryId":"9d35efa9","votedBelt":"Yellow","comment":"NiXXeD\\nVery simple pick, very interesting insides","userId":"WMSvvuutyShfvBBYB3PmDe4fmeS2","displayName":"NiXXeD","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.814Z","updatedAt":"2026-10-09T23:22:56.814Z"},{"id":"v_743f34c7","type":"vote","entryId":"9d35efa9","votedBelt":"Yellow","comment":"Cool rekeying mechanism.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.814Z","updatedAt":"2026-10-09T23:23:56.814Z"},{"id":"v_cd03f4f9","type":"vote","entryId":"d5e0dba9","votedBelt":"Black 1","comment":"13 pins.  Cramped keyway.  Does have true zero lifts.  Required manual counter rotation to set spool pins and created some ping pong.  Makes sense to me to upgrade these up a belt.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.485Z"},{"id":"v_38e83183","type":"vote","entryId":"160ef1d4","votedBelt":"Blue","comment":"Clef\\nnice dimple, only two spools","userId":"tbaq0CWuDTXerA0eUi0kGASVb1Z2","displayName":"Clefmentine","source":"sheet","createdAt":"2026-10-12T23:37:02.485Z"},{"id":"v_6a9075f5","type":"vote","entryId":"f16d49e9","votedBelt":"Green","comment":"6 pins.  Spools and standard drivers that have very clear feedback.  The interactive in the back needs pulled inward toward center of core which is tricky if you're not aware of it but is trivial when you know what to do.  There are grooves in the housing in 3 positions that the interactive locks in so it (interactive only) needs picked 3 times to 360 it.  \\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.485Z"},{"id":"v_7ca8f1f9","type":"vote","entryId":"f16d49e9","votedBelt":"Green","comment":"6 pin dimple. 3 standards 3 spools. Fits adamantly into green\\n\\n-Zehkar","userId":"1SqcRKce18boUZBtOHWSenGAI202","displayName":"Zehkar","source":"sheet","createdAt":"2026-10-12T23:38:02.485Z"},{"id":"v_a6958153","type":"vote","entryId":"6d53f529","votedBelt":"Orange","comment":"6standsrd drivers\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.485Z"},{"id":"v_ff42c658","type":"vote","entryId":"89c7446c","votedBelt":"Black 3","comment":"tonysansan\\n\\nSignificantly easier than both 30B and 30C, as the bitting range is tighter, so false gates less effective and plenty of room for tools even with lowest lifts. But similar core mechanism, so not an easy lock. ","userId":"BJyWOIOsqmRDkgHZBqIEGbGnVSA3","displayName":"tonysansan","source":"sheet","createdAt":"2026-10-12T23:37:02.486Z"},{"id":"v_318b7f0e","type":"vote","entryId":"89c7446c","votedBelt":"Black 5","comment":"I have picked both 30a, and 30b, my 30b has the same disconnected plug/cam as my 30a. i would vote to same line them. -Retep","userId":"u_7e351cf1","displayName":"Retep","source":"sheet","createdAt":"2026-10-12T23:38:02.486Z"},{"id":"v_d5bbb63d","type":"vote","entryId":"288c8f6e","votedBelt":"Blue","comment":"DECODER: Not much difference to Winkhaus N-tra and other similar dimple locks","userId":"Mwbvdkq1QtWu2zLwEaj3imULSry1","displayName":"decoder","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.815Z","updatedAt":"2026-10-09T23:22:56.815Z"},{"id":"v_367a8413","type":"vote","entryId":"10679814","votedBelt":"Blue","comment":"DECODER: Only picked it once, don't have one for retrying. Seemed not so straightforward.","userId":"Mwbvdkq1QtWu2zLwEaj3imULSry1","displayName":"decoder","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.815Z","updatedAt":"2026-10-09T23:22:56.815Z"},{"id":"v_1779e1a3","type":"vote","entryId":"10679814","votedBelt":"Blue","comment":"Need to 360\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T23:23:56.815Z","updatedAt":"2026-10-09T23:23:56.815Z"},{"id":"v_92563dbe","type":"vote","entryId":"42d30266","votedBelt":"Green","comment":"I haven’t picked the 5 pin that’s orange.  This felt orange but maybe it’s worth a bump for the extra pin. \\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.486Z"},{"id":"v_fedd1876","type":"vote","entryId":"c4a2fbe5","votedBelt":"Blue","comment":"Could be green, no security pins, drivers and key pins are rounded where they meet at shear. Only rated blue because you need to search for the binder in the 3 rows. 17 pins in mine.\\n-Mugatu","userId":"u_f278d262","displayName":"Mugatu","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.815Z","updatedAt":"2026-10-09T23:22:56.815Z"},{"id":"v_0cfd0e28","type":"vote","entryId":"837761db","votedBelt":"Blue","comment":"5 pin Winkhaus with interesting security pins. Picked it only once so as soon as I get my hands on another I might update this entry. \\nWith the one pick I had on it, it felt to hard for green if I compare it to Abus 72/40. Even if it has only 5 pins I rate it over green at easy blue. \\nWould like to see more opinions on this. \\n- DigPicks","userId":"U3wCYsdGwYS8ujsO2K78iD68FMC3","displayName":"Dig","source":"sheet","createdAt":"2026-10-12T23:37:02.486Z"},{"id":"v_8cae418d","type":"vote","entryId":"837761db","votedBelt":"Green","comment":"There are some instances of this lock that have difficult bittings, esp in combination with the key spool that they sometimes have. But many of them are somewhat easy to pick, so imho not blue in general. -decoder","userId":"Mwbvdkq1QtWu2zLwEaj3imULSry1","displayName":"decoder","source":"sheet","createdAt":"2026-10-12T23:38:02.486Z"},{"id":"v_7ac5d044","type":"vote","entryId":"6ebce16f","votedBelt":"Red","comment":"Serrations grab hard. Needed a 2in1. could see this being black without a problem. Retep\\n","userId":"u_7e351cf1","displayName":"Retep","source":"sheet","createdAt":"2026-10-12T23:37:02.486Z"},{"id":"v_ad5a1e76","type":"vote","entryId":"e16080de","votedBelt":"Blue","comment":"I picked one from Arti's group buy. \\n The keyway on the customer side is the only real challenge and the bitting of this particular lock with the max or near max lift on #6.  I don't know if all these have the same or similar keyway, but my rating is just based on the one I picked.  If not for the customer keyway and bitting I feel this would be green.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.816Z","updatedAt":"2026-10-09T23:22:56.816Z"},{"id":"v_db4b6bb8","type":"vote","entryId":"7bc9de2d","votedBelt":"Purple","comment":"Should be samelined with BKS Multipin (for which I also voted purple).  Regardless of rank it should be samelined with BKS, it’s the same lock.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"sheet","createdAt":"2026-10-12T23:37:02.487Z"},{"id":"v_9b4ee13f","type":"vote","entryId":"ad6b0d8f","votedBelt":"Yellow","comment":"LockPickingFisherman\\n5 stacks with brass standard drivers in an aluminum body. Muted feedback. It's a weird pick but also kinda fun. A little rougher than Master 141 but not much harder. Definitely not up to orange imho.","userId":"IzvfeUBxzWcd8VXKHq0T4MUhtQu1","displayName":"LockPickingFisherman","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.816Z","updatedAt":"2026-10-09T23:22:56.816Z"},{"id":"v_4a98e029","type":"vote","entryId":"a7ffa199","votedBelt":"Green","comment":"6 standards, 2 spools with poor tolerances. Could feel shifts in the core setting standard pins. Keyway isn’t really restrictive, was able to use tall MP flags to set pins. ","userId":"u_8d658c6e","displayName":"Unknown","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.816Z","updatedAt":"2026-10-09T23:22:56.816Z"},{"id":"v_40d0c614","type":"vote","entryId":"2b6dd267","votedBelt":"Blue","comment":"9 pin plus interactive rather than the stated 8, 2 spools, 1 torpedo keypin, can be a bit tricky if the spool is under a max lift pin, rows don't isolate so some jumping about including the interactive which binds either first clockwise our next to last counterclockwise on the lock I had, could be purple perhaps \\nLockpickingPaul","userId":"SyjMMYh9rYPI0lrxAWu5z5rrawx2","displayName":"Lock Picking Paul","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.816Z","updatedAt":"2026-10-09T23:22:56.816Z"},{"id":"v_5c45a032","type":"vote","entryId":"0757b1ed","votedBelt":"Green","comment":"Poor tolerances and rounded key pins and lack of security pins keep this at green with the other models imo.\\n\\nJim","userId":"UbhgAjZIuLauV1dw2G4QsocHIk83","displayName":"Georgia Jim","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.816Z","updatedAt":"2026-10-09T23:22:56.816Z"},{"id":"v_d2bff87f","type":"vote","entryId":"074db05e","votedBelt":"Green","comment":"Jim\\nOne extra disc really doesn’t add any extra difficulty. ","userId":"UbhgAjZIuLauV1dw2G4QsocHIk83","displayName":"Georgia Jim","source":"Classification Sheet","createdAt":"2026-10-09T23:22:56.816Z","updatedAt":"2026-10-09T23:22:56.816Z"},{"id":"v_33c92ff4","type":"vote","entryId":"64c6e2d3","votedBelt":"Purple","userId":"u_b530fb39","displayName":"Unknown","source":"sheet","createdAt":"2026-10-12T23:37:02.487Z"},{"id":"v_fc33a3f0","type":"vote","entryId":"64c6e2d3","votedBelt":"Add ranks under Chicago Lock Above ","userId":"u_545a2727","displayName":"Unknown","source":"sheet","createdAt":"2026-10-12T23:38:02.487Z"},{"id":"v_b9ad3b7e","type":"vote","entryId":"3f5ed610","votedBelt":"Green","comment":"Jim\\nThese can fall into the American Lock clone category. 6 pins, always pinned one standard, one bump stop and the rest spools. These are made by the same factory that makes Kryptonite, Draper, Matlock, Toledo and some Yale model padlocks. All share the same pinning style and all except for the Matlock have the same American lock keyway. ","userId":"UbhgAjZIuLauV1dw2G4QsocHIk83","displayName":"Georgia Jim","source":"sheet","createdAt":"2026-10-12T23:37:02.487Z"},{"id":"v_72ff9bcb","type":"vote","entryId":"61160e55","votedBelt":"Blue","comment":"Marson\\nMuch like the Miwa DS\\nhttps://www.youtube.com/watch?v=_Iu7u6Mp4j8","userId":"e2RNiz570rWqYYxDSDn6Y0uhgA43","displayName":"Marson","source":"sheet","createdAt":"2026-10-12T23:37:02.487Z"},{"id":"v_ed2623f4","type":"vote","entryId":"cba6a5f1","votedBelt":"Orange","comment":"Seven standard pins, nothing impressive with tolerance, I could see this going yellow. But, I thought 7 pins might be a bit much for somebody at yellow belt skill, so maybe orange. \\n-Doc Hog","userId":"hnX373zhNoT1QZ3lc8IWVEvcz0R2","displayName":"DoctorHogmaster","source":"sheet","createdAt":"2026-10-12T23:37:02.487Z"},{"id":"v_387b5013","type":"vote","entryId":"cba6a5f1","votedBelt":"Orange","comment":"38mm feels Yellow to me but for someone picking at yellow/orange, a 7 pin dimple might feel bigger than that. Same keyway as Yale Superior, lots of room for a tensioner and pick. With light tension pins act slightly tapered but with medium tension, it's a pretty fast pick. Tolerances aren't great. 32mm version has 7 pins, 28.5mm version has 6 pins.\\nLockPickingFisherman","userId":"IzvfeUBxzWcd8VXKHq0T4MUhtQu1","displayName":"LockPickingFisherman","source":"sheet","createdAt":"2026-10-12T23:38:02.487Z"},{"id":"v_80660679","type":"vote","entryId":"ba356969","votedBelt":" ","userId":"u_016885eb","displayName":"Unknown","source":"sheet","createdAt":"2026-10-12T23:44:02.487Z"},{"id":"v_ea2efde1","type":"vote","entryId":"1333f3ac","votedBelt":"Yellow","comment":"Rebranded Master Lock 141. 4 standards, same keyway, 1/3 of the cost. Fun little lock.\\nLockPickingFisherman","userId":"IzvfeUBxzWcd8VXKHq0T4MUhtQu1","displayName":"LockPickingFisherman","source":"sheet","createdAt":"2026-10-12T23:37:02.488Z"}]`);export{e as t};